          message: 'Use the seeded PRNG; Math.random is permitted only in src/sim/prng.ts.'
        }
      ]
    }
  },
  {
    files: ['src/sim/prng.ts'],
    rules: {
      'no-restricted-properties': 'off'
    }
  }
);

export const TICK_RATE = 20;
export const SECONDS_PER_TICK = 1 / TICK_RATE;
export const TILE_SIZE = 32;
export const MAX_ORDER_STALL_TICKS = TICK_RATE * 8;
export const REPATH_INTERVAL_TICKS = TICK_RATE;
export const MAX_REPATH_ATTEMPTS = 8;
export const MIN_UNIT_DISTANCE = 0.5;
export const CAMPAIGN_LEVELS = 5;
export const DEFAULT_SEED = 123456789;
export const RESOURCE_SCAN_RADIUS = 48;
export const AI_THINK_INTERVAL = TICK_RATE;
export const CORPSE_FADE_TICKS = TICK_RATE * 4;
export const PROJECTILE_SPEED_TILES_PER_SECOND = 8;

export type PlayerId = 1 | 2;
export type Faction = 'humans' | 'orcs';
export type UnitKind = 'worker' | 'melee' | 'ranged' | 'heavy';
export type BuildingKind = 'townHall' | 'farm' | 'barracks' | 'lumberMill' | 'guardTower';
export type ResourceKind = 'gold' | 'wood';
export type TileKind = 'grass' | 'dirt' | 'forest' | 'water' | 'rock' | 'goldMine' | 'depletedMine';
export type EntityId = number;
export type GameOutcome = 'playing' | 'victory' | 'defeat';

export interface Point {
  x: number;
  y: number;
}

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface Tile {
  kind: TileKind;
  gold: number;
  wood: number;
}

export interface StartLocation {
  player: PlayerId;
  x: number;
  y: number;
}

export interface GameMap {
  width: number;
  height: number;
  tiles: Tile[];
  starts: [StartLocation, StartLocation];
  level: number;
  seed: number;
  walkVersion: number;
}

export interface Cargo {
  kind: ResourceKind;
  amount: number;
}

export type OrderTerminalReason = 'completed' | 'replaced' | 'cancelled' | 'unreachable' | 'exhausted' | 'no-dropoff' | 'stalled';

export type UnitOrder =
  | { kind: 'idle'; reason?: OrderTerminalReason }
  | { kind: 'move'; target: Point; reachable: boolean }
  | { kind: 'attack'; targetId: EntityId }
  | { kind: 'attackMove'; target: Point; reachable: boolean }
  | { kind: 'harvest'; resource: ResourceKind; source: Point; phase: 'toSource' | 'gathering' | 'toDropoff'; gatherTicks: number }
  | { kind: 'build'; building: BuildingKind; site: Point; phase: 'toSite' | 'constructing' }
  | { kind: 'repair'; targetId: EntityId; phase: 'toTarget' | 'repairing' };

export interface MoveState {
  from: Point;
  to: Point;
  progress: number;
  duration: number;
}

export interface Unit {
  id: EntityId;
  type: 'unit';
  owner: PlayerId;
  faction: Faction;
  kind: UnitKind;
  hp: number;
  tile: Point;
  x: number;
  y: number;
  order: UnitOrder;
  cargo?: Cargo;
  destination?: Point;
  desiredDestination?: Point;
  path: Point[];
  pathVersion: number;
  pathReachable: boolean;
  move?: MoveState;
  attackCooldown: number;
  blockedTicks: number;
  repathAttempts: number;
  lastProgressTick: number;
  lastProgressSignature: string;
  waveTag?: number;
}

export interface TrainingQueueItem {
  kind: UnitKind;
  remainingTicks: number;
  totalTicks: number;
}

export interface BuildProgress {
  remainingTicks: number;
  totalTicks: number;
  workerId: EntityId;
}

export interface Building {
  id: EntityId;
  type: 'building';
  owner: PlayerId;
  faction: Faction;
  kind: BuildingKind;
  hp: number;
  x: number;
  y: number;
  w: number;
  h: number;
  complete: boolean;
  queue: TrainingQueueItem[];
  build?: BuildProgress;
  attackCooldown: number;
}

export interface Projectile {
  id: number;
  owner: PlayerId;
  from: Point;
  x: number;
  y: number;
  targetId: EntityId;
  damage: number;
  remainingTicks: number;
}

export interface Corpse {
  x: number;
  y: number;
  remainingTicks: number;
  owner: PlayerId;
}

export interface PlayerState {
  id: PlayerId;
  faction: Faction;
  gold: number;
  wood: number;
  supplyUsed: number;
  supplyCap: number;
  aiDifficulty: number;
  wavesLaunched: number;
  unlockedLevel: number;
}

export interface FogState {
  explored: Uint8Array;
  visible: Uint8Array;
}

export interface SerializedWorld {
  tick: number;
  outcome: GameOutcome;
  mapHash: string;
  players: string;
  units: string;
  buildings: string;
  projectiles: string;
}

import type { Point, Rect } from './types';

export function keyOf(point: Point): string {
  return `${point.x},${point.y}`;
}

export function tileKey(x: number, y: number): string {
  return `${x},${y}`;
}

export function samePoint(a: Point, b: Point): boolean {
  return a.x === b.x && a.y === b.y;
}

export function distance(a: Point, b: Point): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

export function gridDistance(a: Point, b: Point): number {
  const dx = Math.abs(a.x - b.x);
  const dy = Math.abs(a.y - b.y);
  const diagonal = Math.min(dx, dy);
  const straight = Math.max(dx, dy) - diagonal;
  return diagonal * Math.SQRT2 + straight;
}

export function rectContains(rect: Rect, point: Point): boolean {
  return point.x >= rect.x && point.y >= rect.y && point.x < rect.x + rect.w && point.y < rect.y + rect.h;
}

export function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function centerOfRect(rect: Rect): Point {
  return { x: rect.x + rect.w / 2, y: rect.y + rect.h / 2 };
}

export function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

export function mustGet<K, V>(map: Map<K, V>, key: K, label: string): V {
  const value = map.get(key);
  if (value === undefined) {
    throw new Error(`${label} not found: ${String(key)}`);
  }
  return value;
}

export function assertFinite(value: number, label: string): void {
  if (!Number.isFinite(value)) {
    throw new Error(`${label} is not finite`);
  }
}

export function inBounds(width: number, height: number, x: number, y: number): boolean {
  return x >= 0 && y >= 0 && x < width && y < height;
}

export function spiral(center: Point, radius: number): Point[] {
  const points: Point[] = [];
  for (let r = 0; r <= radius; r += 1) {
    for (let y = center.y - r; y <= center.y + r; y += 1) {
      for (let x = center.x - r; x <= center.x + r; x += 1) {
        if (Math.max(Math.abs(x - center.x), Math.abs(y - center.y)) === r) {
          points.push({ x, y });
        }
      }
    }
  }
  return points;
}

import { DEFAULT_SEED } from './constants';

export interface Prng {
  next(): number;
  int(maxExclusive: number): number;
  range(minInclusive: number, maxExclusive: number): number;
  pickIndex(weights: readonly number[]): number;
  fork(offset: number): Prng;
  seed: number;
}

function normalizeSeed(seed: number): number {
  const normalized = seed >>> 0;
  return normalized === 0 ? DEFAULT_SEED : normalized;
}

export class Mulberry32 implements Prng {
  public readonly seed: number;
  private state: number;

  public constructor(seed: number) {
    this.seed = normalizeSeed(seed);
    this.state = this.seed;
  }

  public next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  public int(maxExclusive: number): number {
    if (maxExclusive <= 0) {
      throw new Error(`maxExclusive must be positive, got ${maxExclusive}`);
    }
    return Math.floor(this.next() * maxExclusive);
  }

  public range(minInclusive: number, maxExclusive: number): number {
    if (maxExclusive <= minInclusive) {
      throw new Error(`invalid range ${minInclusive}..${maxExclusive}`);
    }
    return minInclusive + this.int(maxExclusive - minInclusive);
  }

  public pickIndex(weights: readonly number[]): number {
    const total = weights.reduce((sum, weight) => sum + weight, 0);
    if (total <= 0) {
      throw new Error('cannot pick from empty weight distribution');
    }
    let cursor = this.next() * total;
    for (let i = 0; i < weights.length; i += 1) {
      cursor -= weights[i];
      if (cursor <= 0) {
        return i;
      }
    }
    return weights.length - 1;
  }

  public fork(offset: number): Prng {
    return new Mulberry32((this.seed ^ Math.imul(offset + 1, 0x9e3779b9)) >>> 0);
  }
}

export function seedFromUrl(search: string): number {
  const params = new URLSearchParams(search);
  const value = params.get('seed');
  if (value === null) {
    return freshSeed();
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? normalizeSeed(parsed) : freshSeed();
}

export function freshSeed(): number {
  return normalizeSeed(Math.floor(Math.random() * 0xffffffff));
}

