export function tileIndex(map: GameMap, x: number, y: number): number {
  return y * map.width + x;
}

export function getTile(map: GameMap, x: number, y: number): Tile {
  if (!inBounds(map.width, map.height, x, y)) {
    throw new Error(`tile out of bounds: ${x},${y}`);
  }
  return map.tiles[tileIndex(map, x, y)];
}

export function setTileKind(map: GameMap, x: number, y: number, kind: TileKind): void {
  const tile = getTile(map, x, y);
  const wasWalkable = isTileWalkable(tile.kind);
  tile.kind = kind;
  if (kind !== 'goldMine') {
    tile.gold = 0;
  }
  if (kind !== 'forest') {
    tile.wood = 0;
  }
  if (wasWalkable !== isTileWalkable(kind)) {
    map.walkVersion += 1;
  }
}

export function isTileWalkable(kind: TileKind): boolean {
  return TILE_RULES[kind].walkable;
}

export function isTileBuildable(kind: TileKind): boolean {
  return TILE_RULES[kind].buildable;
}

export function areAdjacentKindsAllowed(a: TileKind, b: TileKind): boolean {
  return TILE_RULES[a].adjacency.includes(b) && TILE_RULES[b].adjacency.includes(a);
}

export function neighbors8(point: Point): Point[] {
  const result: Point[] = [];
  for (let dy = -1; dy <= 1; dy += 1) {
    for (let dx = -1; dx <= 1; dx += 1) {
      if (dx !== 0 || dy !== 0) {
        result.push({ x: point.x + dx, y: point.y + dy });
      }
    }
  }
  return result;
}

export function mapHash(map: GameMap): string {
  let hash = 2166136261;
  for (const tile of map.tiles) {
    for (let i = 0; i < tile.kind.length; i += 1) {
      hash ^= tile.kind.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    hash ^= tile.gold + tile.wood;
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16);
}

import type { Prng } from '../prng';
import type { GameMap, TileKind } from '../types';
import { inBounds } from '../utils';
import { areAdjacentKindsAllowed, COLLAPSIBLE_TILES, createTile, TILE_RULES } from './tiles';

interface CellState {
  options: Set<TileKind>;
}

export interface WfcOptions {
  width: number;
  height: number;
  seed: number;
  level: number;
  waterScale: number;
  rockScale: number;
  forestScale: number;
}

const directions = [
  { x: 1, y: 0 },
  { x: -1, y: 0 },
  { x: 0, y: 1 },
  { x: 0, y: -1 }
];

export function collapseWfc(options: WfcOptions, prng: Prng): GameMap | undefined {
  const cells: CellState[] = Array.from({ length: options.width * options.height }, () => ({
    options: new Set(COLLAPSIBLE_TILES)
  }));
  for (let guard = 0; guard < options.width * options.height; guard += 1) {
    const index = findLowestEntropyCell(cells, prng);
    if (index === undefined) {
      return toMap(cells, options);
    }
    const chosen = chooseOption(cells[index], options, prng);
    cells[index].options = new Set([chosen]);
    if (!propagate(cells, options.width, options.height, index)) {
      return undefined;
    }
  }
  return toMap(cells, options);
}

export function validateAdjacency(map: GameMap): boolean {
  for (let y = 0; y < map.height; y += 1) {
    for (let x = 0; x < map.width; x += 1) {
      const here = map.tiles[y * map.width + x].kind;
      for (const direction of directions) {
        const nx = x + direction.x;
        const ny = y + direction.y;
        if (inBounds(map.width, map.height, nx, ny)) {
          const there = map.tiles[ny * map.width + nx].kind;
          if (!areAdjacentKindsAllowed(here, there)) {
            return false;
          }
        }
      }
    }
  }
  return true;
}

function findLowestEntropyCell(cells: CellState[], prng: Prng): number | undefined {
  let bestEntropy = Number.POSITIVE_INFINITY;
  const candidates: number[] = [];
  for (let i = 0; i < cells.length; i += 1) {
    const count = cells[i].options.size;
    if (count > 1 && count < bestEntropy) {
      bestEntropy = count;
      candidates.length = 0;
      candidates.push(i);
    } else if (count === bestEntropy) {
      candidates.push(i);
    }
  }
  if (candidates.length === 0) {
    return undefined;
  }
  return candidates[prng.int(candidates.length)];
}

function chooseOption(cell: CellState, options: WfcOptions, prng: Prng): TileKind {
  const kinds = Array.from(cell.options);
  const weights = kinds.map(kind => scaledWeight(kind, options));
  return kinds[prng.pickIndex(weights)];
}

function scaledWeight(kind: TileKind, options: WfcOptions): number {
  const base = TILE_RULES[kind].weight;
  if (kind === 'water') {
    return Math.max(1, Math.round(base * options.waterScale));
  }
  if (kind === 'rock') {
    return Math.max(1, Math.round(base * options.rockScale));
  }
  if (kind === 'forest') {
    return Math.max(1, Math.round(base * options.forestScale));
  }
  return base;
}

function propagate(cells: CellState[], width: number, height: number, start: number): boolean {
  const queue = [start];
  while (queue.length > 0) {
    const index = queue.shift();
    if (index === undefined) {
      throw new Error('queue returned undefined after non-empty check');
    }
    const x = index % width;
    const y = Math.floor(index / width);
    for (const direction of directions) {
      const nx = x + direction.x;
      const ny = y + direction.y;
      if (!inBounds(width, height, nx, ny)) {
        continue;
      }
      const neighborIndex = ny * width + nx;
      const neighbor = cells[neighborIndex];
      const before = neighbor.options.size;
      for (const candidate of Array.from(neighbor.options)) {
        if (!hasCompatibleOption(cells[index], candidate)) {
          neighbor.options.delete(candidate);
        }
      }
      if (neighbor.options.size === 0) {
        return false;
      }
      if (neighbor.options.size < before) {
        queue.push(neighborIndex);
      }
    }
  }
  return true;
}

function hasCompatibleOption(source: CellState, candidate: TileKind): boolean {
  for (const sourceKind of source.options) {
    if (areAdjacentKindsAllowed(sourceKind, candidate)) {
      return true;
    }
  }
  return false;
}

function toMap(cells: CellState[], options: WfcOptions): GameMap | undefined {
  const tiles = [];
  for (const cell of cells) {
    if (cell.options.size !== 1) {
      return undefined;
    }
    const [kind] = Array.from(cell.options);
    tiles.push(createTile(kind));
  }
  return {
    width: options.width,
    height: options.height,
    tiles,
    starts: [
      { player: 1, x: 0, y: 0 },
      { player: 2, x: options.width - 1, y: options.height - 1 }
    ],
    level: options.level,
    seed: options.seed,
    walkVersion: 0
  };
}

import type { Point } from './types';
import { gridDistance, inBounds, keyOf, samePoint } from './utils';

export interface GridSpec {
  width: number;
  height: number;
  isBlocked(x: number, y: number): boolean;
}

export interface PathResult {
  path: Point[];
  reachable: boolean;
  destination: Point;
  cost: number;
  visited: number;
}

interface NodeRecord {
  point: Point;
  g: number;
  f: number;
}

const neighborDeltas = [
  { x: -1, y: -1 }, { x: 0, y: -1 }, { x: 1, y: -1 },
  { x: -1, y: 0 }, { x: 1, y: 0 },
  { x: -1, y: 1 }, { x: 0, y: 1 }, { x: 1, y: 1 }
];

export function findPath(grid: GridSpec, start: Point, goal: Point): PathResult {
  const nearestGoal = nearestUnblocked(grid, goal);
  const target = nearestGoal ?? goal;
  if (grid.isBlocked(start.x, start.y)) {
    return { path: [], reachable: false, destination: start, cost: 0, visited: 0 };
  }
  if (nearestGoal === undefined) {
    return searchToClosest(grid, start, goal);
  }
  return aStar(grid, start, target, goal);
}

export function pathDistance(grid: GridSpec, start: Point, goal: Point): number | undefined {
  const result = findPath(grid, start, goal);
  if (!result.reachable || !samePoint(result.destination, goal)) {
    return undefined;
  }
  return result.cost;
}

function aStar(grid: GridSpec, start: Point, target: Point, desired: Point): PathResult {
  if (samePoint(start, target)) {
    return { path: [], reachable: true, destination: target, cost: 0, visited: 1 };
  }
  const open: NodeRecord[] = [{ point: start, g: 0, f: gridDistance(start, target) }];
  const cameFrom = new Map<string, string>();
  const gScore = new Map<string, number>([[keyOf(start), 0]]);
  const closed = new Set<string>();
  let best = start;
  let bestDistance = gridDistance(start, desired);
  while (open.length > 0) {
    const current = popLowest(open);
    const currentKey = keyOf(current.point);
    if (closed.has(currentKey)) {
      continue;
    }
    closed.add(currentKey);
    const desiredDistance = gridDistance(current.point, desired);
    if (desiredDistance < bestDistance) {
      best = current.point;
      bestDistance = desiredDistance;
    }
    if (samePoint(current.point, target)) {
      return {
        path: reconstruct(cameFrom, current.point).slice(1),
        reachable: samePoint(target, desired),
        destination: current.point,
        cost: current.g,
        visited: closed.size
      };
    }
    for (const next of validNeighbors(grid, current.point)) {
      const nextKey = keyOf(next);
      if (closed.has(nextKey)) {
        continue;
      }
      const step = next.x !== current.point.x && next.y !== current.point.y ? Math.SQRT2 : 1;
      const tentative = current.g + step;
      const old = gScore.get(nextKey);
      if (old === undefined || tentative < old) {
        cameFrom.set(nextKey, currentKey);
        gScore.set(nextKey, tentative);
        open.push({ point: next, g: tentative, f: tentative + gridDistance(next, target) });
      }
    }
  }
  const path = reconstruct(cameFrom, best).slice(1);
  return { path, reachable: false, destination: best, cost: pathCost(path, start), visited: closed.size };
}

function searchToClosest(grid: GridSpec, start: Point, desired: Point): PathResult {
  return aStar(grid, start, start, desired);
}

function nearestUnblocked(grid: GridSpec, goal: Point): Point | undefined {
  if (inBounds(grid.width, grid.height, goal.x, goal.y) && !grid.isBlocked(goal.x, goal.y)) {
    return goal;
  }
  const maxRadius = Math.max(grid.width, grid.height);
  for (let radius = 1; radius <= maxRadius; radius += 1) {
    let best: Point | undefined;
    let bestDistance = Number.POSITIVE_INFINITY;
    for (let y = goal.y - radius; y <= goal.y + radius; y += 1) {
      for (let x = goal.x - radius; x <= goal.x + radius; x += 1) {
        if (Math.max(Math.abs(x - goal.x), Math.abs(y - goal.y)) !== radius) {
          continue;
        }
        if (inBounds(grid.width, grid.height, x, y) && !grid.isBlocked(x, y)) {
          const candidate = { x, y };
          const distance = gridDistance(candidate, goal);
          if (distance < bestDistance) {
            best = candidate;
            bestDistance = distance;
          }
        }
      }
    }
    if (best !== undefined) {
      return best;
    }
  }
  return undefined;
}

export function validNeighbors(grid: GridSpec, point: Point): Point[] {
  const result: Point[] = [];
  for (const delta of neighborDeltas) {
    const x = point.x + delta.x;
    const y = point.y + delta.y;
    if (!inBounds(grid.width, grid.height, x, y) || grid.isBlocked(x, y)) {
      continue;
    }
    if (delta.x !== 0 && delta.y !== 0) {
      if (grid.isBlocked(point.x + delta.x, point.y) || grid.isBlocked(point.x, point.y + delta.y)) {
        continue;
      }
    }
    result.push({ x, y });
  }
  return result;
}

function popLowest(open: NodeRecord[]): NodeRecord {
  let bestIndex = 0;
  let bestF = open[0].f;
  for (let i = 1; i < open.length; i += 1) {
    if (open[i].f < bestF) {
      bestIndex = i;
      bestF = open[i].f;
    }
  }
  const [record] = open.splice(bestIndex, 1);
  if (record === undefined) {
    throw new Error('open set underflow');
  }
  return record;
}

function reconstruct(cameFrom: Map<string, string>, end: Point): Point[] {
  const points = [end];
  let cursor = keyOf(end);
  while (cameFrom.has(cursor)) {
    const previous = cameFrom.get(cursor);
    if (previous === undefined) {
      throw new Error('path predecessor missing');
    }
    const parsed = parseKey(previous);
    points.push(parsed);
    cursor = previous;
  }
  return points.reverse();
}

function parseKey(key: string): Point {
  const parts = key.split(',');
  if (parts.length !== 2) {
    throw new Error(`invalid point key ${key}`);
  }
  return { x: Number.parseInt(parts[0], 10), y: Number.parseInt(parts[1], 10) };
}

function pathCost(path: Point[], start: Point): number {
  let total = 0;
  let previous = start;
  for (const point of path) {
    total += point.x !== previous.x && point.y !== previous.y ? Math.SQRT2 : 1;
    previous = point;
  }
  return total;
}

import { BALANCE } from '../stats';
import type { GameMap, Point, StartLocation, TileKind } from '../types';
import { gridDistance, inBounds } from '../utils';
import { findPath, pathDistance, type GridSpec } from '../pathfinding';
import { Mulberry32 } from '../prng';
import { createTile, getTile, isTileBuildable, isTileWalkable, setTileKind } from './tiles';
import { collapseWfc, validateAdjacency } from './wfc';

export interface LevelConfig {
  level: number;
  size: number;
  waterScale: number;
  rockScale: number;
  forestScale: number;
  aiDifficulty: number;
}

export interface PlayabilityReport {
  ok: boolean;
  landDistance: number;
  straightDistance: number;
  startBuildable: boolean;
  reachable: boolean;
  resourcesNear: boolean;
  fairResources: boolean;
}

const LEVELS: LevelConfig[] = [
  { level: 1, size: 32, waterScale: 0.65, rockScale: 0.65, forestScale: 0.9, aiDifficulty: 1 },
  { level: 2, size: 48, waterScale: 0.85, rockScale: 0.85, forestScale: 1.0, aiDifficulty: 2 },
  { level: 3, size: 64, waterScale: 1.05, rockScale: 1.05, forestScale: 1.05, aiDifficulty: 3 },
  { level: 4, size: 80, waterScale: 1.2, rockScale: 1.25, forestScale: 1.0, aiDifficulty: 4 },
  { level: 5, size: 96, waterScale: 1.35, rockScale: 1.4, forestScale: 0.9, aiDifficulty: 5 }
];

export function levelConfig(level: number): LevelConfig {
  const config = LEVELS[level - 1];
  if (config === undefined) {
    throw new Error(`invalid campaign level ${level}`);
  }
  return config;
}

export function createCampaignMap(campaignSeed: number, level: number): GameMap {
  const config = levelConfig(level);
  const levelSeed = (campaignSeed ^ Math.imul(level, 0x45d9f3b)) >>> 0;
  const basePrng = new Mulberry32(levelSeed);
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const attemptSeed = (levelSeed + Math.imul(attempt + 1, 0x9e3779b9)) >>> 0;
    const map = collapseWfc({ ...config, width: config.size, height: config.size, seed: attemptSeed }, basePrng.fork(attempt));
    if (map !== undefined) {
      repairMap(map, config, levelSeed);
      const report = analyzePlayability(map);
      if (validateAdjacency(map) && report.ok) {
        return map;
      }
    }
  }
  const fallback = createGrassMap(config.size, config.size, levelSeed, level);
  repairMap(fallback, config, levelSeed);
  if (!validateAdjacency(fallback)) {
    throw new Error('deterministic repair produced invalid adjacency');
  }
  return fallback;
}

export function analyzePlayability(map: GameMap): PlayabilityReport {
  const a = map.starts[0];
  const b = map.starts[1];
  const grid = mapGrid(map);
  const landDistance = pathDistance(grid, pointOf(a), pointOf(b));
  const straightDistance = gridDistance(pointOf(a), pointOf(b));
  const larger = Math.max(map.width, map.height);
  const reachable = landDistance !== undefined;
  const startBuildable = hasBuildableSquare(map, pointOf(a)) && hasBuildableSquare(map, pointOf(b));
  const resourcesNear = hasResourceNear(map, pointOf(a), 'goldMine') && hasResourceNear(map, pointOf(a), 'forest')
    && hasResourceNear(map, pointOf(b), 'goldMine') && hasResourceNear(map, pointOf(b), 'forest');
  const fairResources = resourceScore(map, pointOf(a)) >= 0.7 && resourceScore(map, pointOf(b)) >= 0.7;
  const distanceValue = landDistance ?? 0;
  return {
    ok: reachable && distanceValue >= larger * 0.6 && straightDistance >= larger * 0.4 && startBuildable && resourcesNear && fairResources,
    landDistance: distanceValue,
    straightDistance,
    startBuildable,
    reachable,
    resourcesNear,
    fairResources
  };
}

export function mapGrid(map: GameMap): GridSpec {
  return {
    width: map.width,
    height: map.height,
    isBlocked: (x, y) => !inBounds(map.width, map.height, x, y) || !isTileWalkable(getTile(map, x, y).kind)
  };
}

function repairMap(map: GameMap, config: LevelConfig, levelSeed: number): void {
  map.starts = startsFor(map.width, map.height);
  const startA = pointOf(map.starts[0]);
  const startB = pointOf(map.starts[1]);
  clearBase(map, startA);
  clearBase(map, startB);
  carveCorridor(map, startA, startB, config.level);
  addChokepoints(map, startA, startB, config.level, levelSeed);
  placeStartResources(map, startA, 1);
  placeStartResources(map, startB, -1);
  map.walkVersion += 1;
}

function startsFor(width: number, height: number): [StartLocation, StartLocation] {
  const margin = Math.max(6, Math.floor(Math.min(width, height) * 0.13));
  return [
    { player: 1, x: margin, y: margin },
    { player: 2, x: width - margin - 1, y: height - margin - 1 }
  ];
}

function clearBase(map: GameMap, center: Point): void {
  for (let y = center.y - 5; y <= center.y + 5; y += 1) {
    for (let x = center.x - 5; x <= center.x + 5; x += 1) {
      if (inBounds(map.width, map.height, x, y)) {
        setPlain(map, x, y, Math.abs(x - center.x) <= 3 && Math.abs(y - center.y) <= 3 ? 'grass' : 'dirt');
      }
    }
  }
}

function carveCorridor(map: GameMap, from: Point, to: Point, level: number): void {
  const steps = Math.max(Math.abs(to.x - from.x), Math.abs(to.y - from.y));
  for (let i = 0; i <= steps; i += 1) {
    const t = i / steps;
    const x = Math.round(from.x + (to.x - from.x) * t);
    const y = Math.round(from.y + (to.y - from.y) * t);
    const width = level >= 4 && i > steps * 0.35 && i < steps * 0.65 ? 1 : 2;
    for (let dy = -width; dy <= width; dy += 1) {
      for (let dx = -width; dx <= width; dx += 1) {
        if (inBounds(map.width, map.height, x + dx, y + dy)) {
          setPlain(map, x + dx, y + dy, 'dirt');
        }
      }
    }
  }
}

function addChokepoints(map: GameMap, from: Point, to: Point, level: number, seed: number): void {
  if (level < 3) {
    return;
  }
  const midpoint = { x: Math.floor((from.x + to.x) / 2), y: Math.floor((from.y + to.y) / 2) };
  const half = Math.min(6 + level, Math.floor(map.width / 6));
  const orientation = seed % 2 === 0 ? 'vertical' : 'horizontal';
  for (let offset = -half; offset <= half; offset += 1) {
    for (let band = -1; band <= 1; band += 1) {
      const x = orientation === 'vertical' ? midpoint.x + band : midpoint.x + offset;
      const y = orientation === 'vertical' ? midpoint.y + offset : midpoint.y + band;
      if (inBounds(map.width, map.height, x, y) && Math.abs(offset) > 1) {
        setPlain(map, x, y, 'rock');
      }
    }
  }
}

function placeStartResources(map: GameMap, start: Point, direction: 1 | -1): void {
  placeGold(map, { x: start.x + direction * 6, y: start.y + 1 });
  placeForest(map, { x: start.x - direction * 5, y: start.y + 6 });
  placeForest(map, { x: start.x + direction * 2, y: start.y - 7 });
}

function placeGold(map: GameMap, point: Point): void {
  for (let y = point.y - 2; y <= point.y + 2; y += 1) {
    for (let x = point.x - 2; x <= point.x + 2; x += 1) {
      if (inBounds(map.width, map.height, x, y)) {
        setPlain(map, x, y, 'dirt');
      }
    }
  }
  if (inBounds(map.width, map.height, point.x, point.y)) {
    setPlain(map, point.x, point.y, 'goldMine');
    getTile(map, point.x, point.y).gold = BALANCE.mineGold;
  }
}

function placeForest(map: GameMap, point: Point): void {
  for (let y = point.y - 2; y <= point.y + 2; y += 1) {
    for (let x = point.x - 2; x <= point.x + 2; x += 1) {
      if (inBounds(map.width, map.height, x, y)) {
        setPlain(map, x, y, 'grass');
      }
    }
  }
  const trees = [point, { x: point.x + 1, y: point.y }, { x: point.x, y: point.y + 1 }, { x: point.x - 1, y: point.y }];
  for (const tree of trees) {
    if (inBounds(map.width, map.height, tree.x, tree.y)) {
      setPlain(map, tree.x, tree.y, 'forest');
      getTile(map, tree.x, tree.y).wood = BALANCE.forestWood;
    }
  }
}

function hasBuildableSquare(map: GameMap, center: Point): boolean {
  for (let y = center.y - 2; y <= center.y + 2; y += 1) {
    for (let x = center.x - 2; x <= center.x + 2; x += 1) {
      if (!inBounds(map.width, map.height, x, y) || !isTileBuildable(getTile(map, x, y).kind)) {
        return false;
      }
    }
  }
  return true;
}

function hasResourceNear(map: GameMap, start: Point, kind: TileKind): boolean {
  for (let y = Math.max(0, start.y - 15); y <= Math.min(map.height - 1, start.y + 15); y += 1) {
    for (let x = Math.max(0, start.x - 15); x <= Math.min(map.width - 1, start.x + 15); x += 1) {
      if (getTile(map, x, y).kind === kind) {
        const result = findPath(mapGrid(map), start, nearestAdjacent(map, { x, y }));
        if (result.path.length <= 15) {
          return true;
        }
      }
    }
  }
  return false;
}

function nearestAdjacent(map: GameMap, point: Point): Point {
  for (let radius = 1; radius <= 2; radius += 1) {
    for (let y = point.y - radius; y <= point.y + radius; y += 1) {
      for (let x = point.x - radius; x <= point.x + radius; x += 1) {
        if (inBounds(map.width, map.height, x, y) && isTileWalkable(getTile(map, x, y).kind)) {
          return { x, y };
        }
      }
    }
  }
  return point;
}

function resourceScore(map: GameMap, start: Point): number {
  let gold = 0;
  let wood = 0;
  for (let y = Math.max(0, start.y - 15); y <= Math.min(map.height - 1, start.y + 15); y += 1) {
    for (let x = Math.max(0, start.x - 15); x <= Math.min(map.width - 1, start.x + 15); x += 1) {
      const tile = getTile(map, x, y);
      gold += tile.gold;
      wood += tile.wood;
    }
  }
  return Math.min(gold / BALANCE.mineGold, wood / (BALANCE.forestWood * 4));
}

function setPlain(map: GameMap, x: number, y: number, kind: TileKind): void {
  setTileKind(map, x, y, kind);
}

function createGrassMap(width: number, height: number, seed: number, level: number): GameMap {
  return {
    width,
    height,
    tiles: Array.from({ length: width * height }, () => createTile('grass')),
    starts: startsFor(width, height),
    level,
    seed,
    walkVersion: 0
  };
}

function pointOf(start: StartLocation): Point {
  return { x: start.x, y: start.y };
}

import { buildingStats } from './stats';
import type { Building, BuildingKind, GameMap, Point, Unit } from './types';
import { getTile, isTileBuildable } from './map/tiles';
import { inBounds } from './utils';

export interface PlacementContext {
  map: GameMap;
  buildings: Iterable<Building>;
  units: Iterable<Unit>;
}

export interface PlacementResult {
  ok: boolean;
  reason?: 'out-of-bounds' | 'terrain' | 'building' | 'unit';
}

export function validatePlacement(context: PlacementContext, kind: BuildingKind, site: Point): PlacementResult {
  const footprint = buildingStats(kind).footprint;
  for (let y = site.y; y < site.y + footprint.h; y += 1) {
    for (let x = site.x; x < site.x + footprint.w; x += 1) {
      if (!inBounds(context.map.width, context.map.height, x, y)) {
        return { ok: false, reason: 'out-of-bounds' };
      }
      if (!isTileBuildable(getTile(context.map, x, y).kind)) {
        return { ok: false, reason: 'terrain' };
      }
    }
  }
  for (const building of context.buildings) {
    if (rectsOverlapGrid(site, footprint, { x: building.x, y: building.y }, { w: building.w, h: building.h })) {
      return { ok: false, reason: 'building' };
    }
  }
  for (const unit of context.units) {
    if (unit.tile.x >= site.x && unit.tile.x < site.x + footprint.w && unit.tile.y >= site.y && unit.tile.y < site.y + footprint.h) {
      return { ok: false, reason: 'unit' };
    }
  }
  return { ok: true };
}

function rectsOverlapGrid(a: Point, as: { w: number; h: number }, b: Point, bs: { w: number; h: number }): boolean {
  return a.x < b.x + bs.w && a.x + as.w > b.x && a.y < b.y + bs.h && a.y + as.h > b.y;
}

