import { BALANCE, buildingStats } from '../stats';
import type { Building, Point, Unit } from '../types';
import { getTile } from '../map/tiles';
import { distance } from '../utils';
import type { World } from '../world';

export function tickHarvestAndWork(world: World): void {
  for (const unit of Array.from(world.units.values())) {
    if (unit.kind !== 'worker') {
      continue;
    }
    if (unit.order.kind === 'harvest') {
      tickHarvest(world, unit);
    } else if (unit.order.kind === 'build') {
      tickBuild(world, unit);
    } else if (unit.order.kind === 'repair') {
      tickRepair(world, unit);
    }
  }
}

function tickHarvest(world: World, worker: Unit): void {
  const order = worker.order;
  if (order.kind !== 'harvest') {
    return;
  }
  if (order.phase !== 'toDropoff' && !sourceStillValid(world, order.source, order.resource)) {
    if (!retargetSource(world, worker)) {
      const dropoff = worker.cargo === undefined ? undefined : world.nearestDropoff(worker.owner, worker.cargo.kind, worker.tile);
      if (dropoff !== undefined && worker.cargo !== undefined) {
        order.phase = 'toDropoff';
      } else {
        world.replaceOrder(worker, { kind: 'idle', reason: order.resource === 'gold' ? 'exhausted' : 'cancelled' });
      }
    }
    return;
  }
  if (order.phase === 'toSource') {
    const adjacent = world.nearestAdjacentToTile(order.source, worker.tile);
    if (adjacent === undefined) {
      worker.blockedTicks += 1;
      return;
    }
    if (isAdjacent(worker.tile, order.source)) {
      worker.destination = undefined;
      worker.path = [];
      order.phase = 'gathering';
      order.gatherTicks = order.resource === 'gold' ? BALANCE.goldGatherTicks : BALANCE.woodGatherTicks;
    } else {
      moveToward(world, worker, adjacent);
    }
  } else if (order.phase === 'gathering') {
    gather(world, worker);
  } else {
    deliver(world, worker);
  }
}

function gather(world: World, worker: Unit): void {
  const order = worker.order;
  if (order.kind !== 'harvest') {
    return;
  }
  if (!sourceStillValid(world, order.source, order.resource)) {
    retargetSource(world, worker);
    return;
  }
  order.gatherTicks -= 1;
  if (order.gatherTicks > 0) {
    return;
  }
  const tile = getTile(world.map, order.source.x, order.source.y);
  const available = order.resource === 'gold' ? tile.gold : tile.wood;
  const amount = Math.min(BALANCE.workerCarry, available);
  if (amount <= 0) {
    retargetSource(world, worker);
    return;
  }
  if (order.resource === 'gold') {
    tile.gold -= amount;
    world.markTileChanged(order.source, 'goldMine');
  } else {
    tile.wood -= amount;
    world.markTileChanged(order.source, 'forest');
  }
  worker.cargo = { kind: order.resource, amount };
  order.phase = 'toDropoff';
}

function deliver(world: World, worker: Unit): void {
  if (worker.cargo === undefined) {
    const order = worker.order;
    if (order.kind === 'harvest') {
      order.phase = 'toSource';
    }
    return;
  }
  const dropoff = world.nearestDropoff(worker.owner, worker.cargo.kind, worker.tile);
  if (dropoff === undefined) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'no-dropoff' });
    return;
  }
  const adjacent = world.nearestAdjacentToBuilding(dropoff, worker.tile);
  if (adjacent === undefined) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'no-dropoff' });
    return;
  }
  if (isAdjacentToBuilding(worker.tile, dropoff)) {
    const player = world.player(worker.owner);
    if (worker.cargo.kind === 'gold') {
      player.gold += worker.cargo.amount;
    } else {
      player.wood += worker.cargo.amount;
    }
    const resource = worker.cargo.kind;
    worker.cargo = undefined;
    const order = worker.order;
    if (order.kind === 'harvest') {
      if (sourceStillValid(world, order.source, resource) || retargetSource(world, worker)) {
        const next = worker.order;
        if (next.kind === 'harvest') {
          next.phase = 'toSource';
        }
      } else {
        world.replaceOrder(worker, { kind: 'idle', reason: 'exhausted' });
      }
    }
  } else {
    moveToward(world, worker, adjacent);
  }
}

function tickBuild(world: World, worker: Unit): void {
  const order = worker.order;
  if (order.kind !== 'build') {
    return;
  }
  const building = Array.from(world.buildings.values()).find(candidate => candidate.owner === worker.owner && candidate.x === order.site.x && candidate.y === order.site.y && !candidate.complete);
  if (building === undefined || building.build === undefined) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'completed' });
    return;
  }
  const adjacent = world.nearestAdjacentToBuilding(building, worker.tile);
  if (adjacent === undefined) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'unreachable' });
    return;
  }
  if (!isAdjacentToBuilding(worker.tile, building)) {
    moveToward(world, worker, adjacent);
    return;
  }
  building.build.remainingTicks -= 1;
  const stats = buildingStats(building.kind);
  const completed = 1 - building.build.remainingTicks / building.build.totalTicks;
  building.hp = Math.max(building.hp, Math.max(1, Math.floor(stats.hp * completed)));
  if (building.build.remainingTicks <= 0) {
    world.completeBuilding(building);
    world.replaceOrder(worker, { kind: 'idle', reason: 'completed' });
  }
}

function tickRepair(world: World, worker: Unit): void {
  const order = worker.order;
  if (order.kind !== 'repair') {
    return;
  }
  const building = world.buildings.get(order.targetId);
  if (building === undefined || building.owner !== worker.owner) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'cancelled' });
    return;
  }
  const stats = buildingStats(building.kind);
  if (building.hp >= stats.hp) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'completed' });
    return;
  }
  const adjacent = world.nearestAdjacentToBuilding(building, worker.tile);
  if (adjacent === undefined) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'unreachable' });
    return;
  }
  if (!isAdjacentToBuilding(worker.tile, building)) {
    moveToward(world, worker, adjacent);
    return;
  }
  const repaired = Math.min(BALANCE.repairHpPerTick, stats.hp - building.hp);
  const cost = repaired * BALANCE.repairWoodPerHp;
  if (world.player(worker.owner).wood < cost) {
    world.replaceOrder(worker, { kind: 'idle', reason: 'cancelled' });
    return;
  }
  world.player(worker.owner).wood -= cost;
  building.hp += repaired;
}

function retargetSource(world: World, worker: Unit): boolean {
  const order = worker.order;
  if (order.kind !== 'harvest') {
    return false;
  }
  const replacement = world.nearestResource(order.resource, worker.tile);
  if (replacement === undefined) {
    return false;
  }
  order.source = replacement;
  order.phase = 'toSource';
  order.gatherTicks = 0;
  return true;
}

function sourceStillValid(world: World, source: Point, resource: 'gold' | 'wood'): boolean {
  const tile = getTile(world.map, source.x, source.y);
  return resource === 'gold' ? tile.kind === 'goldMine' && tile.gold > 0 : tile.kind === 'forest' && tile.wood > 0;
}

function moveToward(world: World, worker: Unit, target: Point): void {
  if (worker.move !== undefined) {
    return;
  }
  if (worker.destination === undefined || !sameDestination(worker.destination, target)) {
    world.setDestination(worker, target);
  }
}

function sameDestination(a: Point, b: Point): boolean {
  return a.x === b.x && a.y === b.y;
}

function isAdjacent(a: Point, b: Point): boolean {
  return Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y)) === 1;
}

function isAdjacentToBuilding(point: Point, building: Building): boolean {
  const nearestX = Math.max(building.x, Math.min(point.x, building.x + building.w - 1));
  const nearestY = Math.max(building.y, Math.min(point.y, building.y + building.h - 1));
  return distance(point, { x: nearestX, y: nearestY }) <= Math.SQRT2;
}

import type { World } from '../world';

export function tickProduction(world: World): void {
  for (const building of Array.from(world.buildings.values())) {
    if (!building.complete || building.queue.length === 0) {
      continue;
    }
    const item = building.queue[0];
    if (item === undefined) {
      throw new Error('queue unexpectedly empty');
    }
    item.remainingTicks -= 1;
    if (item.remainingTicks > 0) {
      continue;
    }
    const spawn = world.findSpawnTile(building);
    if (spawn === undefined) {
      item.remainingTicks = 1;
      continue;
    }
    world.spawnUnit(building.owner, item.kind, spawn, false);
    building.queue.shift();
  }
}

import { PROJECTILE_SPEED_TILES_PER_SECOND, TICK_RATE } from '../constants';
import { buildingStats, unitStats } from '../stats';
import type { Building, EntityId, PlayerId, Point, Unit } from '../types';
import { distance } from '../utils';
import type { World } from '../world';

export function tickCombat(world: World): void {
  for (const unit of world.units.values()) {
    unit.attackCooldown = Math.max(0, unit.attackCooldown - 1);
  }
  for (const building of world.buildings.values()) {
    building.attackCooldown = Math.max(0, building.attackCooldown - 1);
  }
  for (const unit of Array.from(world.units.values()).sort((a, b) => a.id - b.id)) {
    tickUnitCombat(world, unit);
  }
  for (const building of Array.from(world.buildings.values()).sort((a, b) => a.id - b.id)) {
    tickBuildingCombat(world, building);
  }
}

export function tickProjectiles(world: World): void {
  for (const projectile of world.projectiles) {
    projectile.remainingTicks -= 1;
    const ratio = projectile.remainingTicks <= 0 ? 1 : 0.75;
    const target = entityPosition(world, projectile.targetId) ?? projectile.from;
    projectile.x += (target.x - projectile.x) * ratio;
    projectile.y += (target.y - projectile.y) * ratio;
  }
  for (let i = world.projectiles.length - 1; i >= 0; i -= 1) {
    const projectile = world.projectiles[i];
    if (projectile.remainingTicks <= 0) {
      applyDamage(world, projectile.targetId, projectile.damage);
      world.projectiles.splice(i, 1);
    }
  }
}

export function computeDamage(attack: number, armor: number): number {
  return Math.max(1, attack - armor);
}

function tickUnitCombat(world: World, unit: Unit): void {
  const stats = unitStats(unit.faction, unit.kind);
  const explicitTarget = unit.order.kind === 'attack' ? unit.order.targetId : undefined;
  let targetId = explicitTarget;
  if (targetId === undefined && (unit.order.kind === 'idle' || unit.order.kind === 'attackMove')) {
    targetId = findHostileInRange(world, unit.owner, unitCenter(unit), stats.sight);
  }
  if (targetId === undefined) {
    return;
  }
  const targetPosition = entityPosition(world, targetId);
  if (targetPosition === undefined) {
    if (unit.order.kind === 'attack') {
      world.replaceOrder(unit, { kind: 'idle', reason: 'completed' });
    }
    return;
  }
  if (distance(unitCenter(unit), targetPosition) <= stats.range) {
    unit.destination = undefined;
    unit.path = [];
    if (unit.attackCooldown <= 0) {
      fire(world, unit.owner, unitCenter(unit), targetId, stats.damage, stats.range > 1.5);
      unit.attackCooldown = stats.cooldownTicks;
    }
  } else if (unit.order.kind === 'attack') {
    world.setDestination(unit, { x: Math.floor(targetPosition.x), y: Math.floor(targetPosition.y) });
  }
}

function tickBuildingCombat(world: World, building: Building): void {
  const stats = buildingStats(building.kind);
  if (!building.complete || stats.damage <= 0 || building.attackCooldown > 0) {
    return;
  }
  const center = buildingCenter(building);
  const targetId = findHostileInRange(world, building.owner, center, stats.range);
  if (targetId !== undefined) {
    fire(world, building.owner, center, targetId, stats.damage, true);
    building.attackCooldown = stats.cooldownTicks;
  }
}

function fire(world: World, owner: PlayerId, from: Point, targetId: EntityId, attack: number, projectile: boolean): void {
  const armor = entityArmor(world, targetId);
  if (armor === undefined) {
    return;
  }
  const damage = computeDamage(attack, armor);
  if (!projectile) {
    applyDamage(world, targetId, damage);
    return;
  }
  const target = entityPosition(world, targetId);
  if (target === undefined) {
    return;
  }
  const travelTicks = Math.max(1, Math.ceil((distance(from, target) / PROJECTILE_SPEED_TILES_PER_SECOND) * TICK_RATE));
  world.projectiles.push({ id: world.tickCount * 100000 + world.projectiles.length, owner, from: { ...from }, x: from.x, y: from.y, targetId, damage, remainingTicks: travelTicks });
}

function applyDamage(world: World, targetId: EntityId, damage: number): void {
  if (world.units.has(targetId) || world.buildings.has(targetId)) {
    world.damageEntity(targetId, damage);
  }
}

function findHostileInRange(world: World, owner: PlayerId, from: Point, range: number): EntityId | undefined {
  let best: EntityId | undefined;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const unit of world.units.values()) {
    if (unit.owner !== owner) {
      const d = distance(from, unitCenter(unit));
      if (d <= range && d < bestDistance) {
        best = unit.id;
        bestDistance = d;
      }
    }
  }
  for (const building of world.buildings.values()) {
    if (building.owner !== owner) {
      const d = distance(from, buildingCenter(building));
      if (d <= range && d < bestDistance) {
        best = building.id;
        bestDistance = d;
      }
    }
  }
  return best;
}

function entityPosition(world: World, id: EntityId): Point | undefined {
  const unit = world.units.get(id);
  if (unit !== undefined) {
    return unitCenter(unit);
  }
  const building = world.buildings.get(id);
  return building === undefined ? undefined : buildingCenter(building);
}

function entityArmor(world: World, id: EntityId): number | undefined {
  const unit = world.units.get(id);
  if (unit !== undefined) {
    return unitStats(unit.faction, unit.kind).armor;
  }
  const building = world.buildings.get(id);
  return building === undefined ? undefined : buildingStats(building.kind).armor;
}

function unitCenter(unit: Unit): Point {
  return { x: unit.x, y: unit.y };
}

function buildingCenter(building: Building): Point {
  return { x: building.x + building.w / 2, y: building.y + building.h / 2 };
}

import { buildingStats, unitStats } from '../stats';
import type { PlayerId, Point } from '../types';
import { distance, inBounds, mustGet } from '../utils';
import type { World } from '../world';

export function tickFog(world: World): void {
  for (const player of [1, 2] as const) {
    const fog = mustGet(world.fog, player, 'fog');
    fog.visible.fill(0);
    for (const unit of world.units.values()) {
      if (unit.owner === player) {
        reveal(world, player, { x: unit.x, y: unit.y }, unitStats(unit.faction, unit.kind).sight);
      }
    }
    for (const building of world.buildings.values()) {
      if (building.owner === player) {
        reveal(world, player, { x: building.x + building.w / 2, y: building.y + building.h / 2 }, buildingStats(building.kind).sight);
      }
    }
  }
}

function reveal(world: World, player: PlayerId, center: Point, radius: number): void {
  const fog = mustGet(world.fog, player, 'fog');
  const minX = Math.max(0, Math.floor(center.x - radius));
  const maxX = Math.min(world.map.width - 1, Math.ceil(center.x + radius));
  const minY = Math.max(0, Math.floor(center.y - radius));
  const maxY = Math.min(world.map.height - 1, Math.ceil(center.y + radius));
  for (let y = minY; y <= maxY; y += 1) {
    for (let x = minX; x <= maxX; x += 1) {
      if (inBounds(world.map.width, world.map.height, x, y) && distance(center, { x: x + 0.5, y: y + 0.5 }) <= radius) {
        const index = y * world.map.width + x;
        fog.visible[index] = 1;
        fog.explored[index] = 1;
      }
    }
  }
}

import { MAX_ORDER_STALL_TICKS, MIN_UNIT_DISTANCE } from '../constants';
import { getTile, isTileWalkable } from '../map/tiles';
import { validNeighbors } from '../pathfinding';
import type { Unit } from '../types';
import { assertFinite, distance } from '../utils';
import type { World } from '../world';

export function assertWorldInvariants(world: World): void {
  for (const player of world.players.values()) {
    assertNonNegative(player.gold, 'gold');
    assertNonNegative(player.wood, 'wood');
    assertNonNegative(player.supplyUsed, 'supplyUsed');
    assertNonNegative(player.supplyCap, 'supplyCap');
  }
  const units = Array.from(world.units.values());
  for (const unit of units) {
    assertUnit(world, unit);
  }
  for (const building of world.buildings.values()) {
    assertNonNegative(building.hp, `building ${building.id} hp`);
  }
  for (let i = 0; i < units.length; i += 1) {
    for (let j = i + 1; j < units.length; j += 1) {
      const separation = distance({ x: units[i].x, y: units[i].y }, { x: units[j].x, y: units[j].y });
      if (separation < MIN_UNIT_DISTANCE) {
        throw new Error(`units ${units[i].id} and ${units[j].id} overlap at distance ${separation}`);
      }
    }
  }
}

function assertUnit(world: World, unit: Unit): void {
  assertNonNegative(unit.hp, `unit ${unit.id} hp`);
  assertFinite(unit.x, `unit ${unit.id} x`);
  assertFinite(unit.y, `unit ${unit.id} y`);
  if (!isTileWalkable(getTile(world.map, unit.tile.x, unit.tile.y).kind)) {
    throw new Error(`unit ${unit.id} occupies unwalkable tile ${unit.tile.x},${unit.tile.y}`);
  }
  if (world.buildingAtTile(unit.tile.x, unit.tile.y) !== undefined) {
    throw new Error(`unit ${unit.id} occupies building footprint`);
  }
  if (unit.move !== undefined) {
    if (world.staticGrid().isBlocked(unit.move.to.x, unit.move.to.y)) {
      throw new Error(`unit ${unit.id} moves into blocked tile`);
    }
    const neighbors = validNeighbors(world.staticGrid(), unit.move.from);
    if (!neighbors.some(point => point.x === unit.move.to.x && point.y === unit.move.to.y)) {
      throw new Error(`unit ${unit.id} movement cuts a blocked corner`);
    }
  }
  if (unit.order.kind !== 'idle' && world.tickCount - unit.lastProgressTick > MAX_ORDER_STALL_TICKS + 1) {
    throw new Error(`unit ${unit.id} active order exceeded progress watchdog`);
  }
}

function assertNonNegative(value: number, label: string): void {
  assertFinite(value, label);
  if (value < 0) {
    throw new Error(`${label} is negative`);
  }
}

import { TICK_RATE } from '../constants';
import { validatePlacement } from '../placement';
import { BALANCE, buildingStats } from '../stats';
import type { BuildingKind, EntityId, PlayerId, Point, UnitKind } from '../types';
import { distance, spiral } from '../utils';
import type { World } from '../world';

const desiredBuildings: BuildingKind[] = ['farm', 'barracks', 'lumberMill', 'guardTower'];

export function tickAi(world: World, owner: PlayerId): void {
  const player = world.player(owner);
  player.gold += Math.max(0, player.aiDifficulty - 1);
  player.wood += Math.max(0, player.aiDifficulty - 1);
  assignWorkers(world, owner);
  rebuildTownHall(world, owner);
  maintainBuildOrder(world, owner);
  trainUnits(world, owner);
  defendBase(world, owner);
  launchWaves(world, owner);
}

function assignWorkers(world: World, owner: PlayerId): void {
  const workers = unitsOf(world, owner, 'worker');
  workers.forEach((worker, index) => {
    if (worker.order.kind !== 'idle') {
      return;
    }
    const resource = index % 3 === 0 ? 'wood' : 'gold';
    const source = world.nearestResource(resource, worker.tile) ?? world.nearestResource(resource === 'gold' ? 'wood' : 'gold', worker.tile);
    if (source !== undefined) {
      world.issueHarvest(worker.id, source);
    }
  });
}

function rebuildTownHall(world: World, owner: PlayerId): void {
  if (hasBuilding(world, owner, 'townHall')) {
    return;
  }
  ensureResources(world, owner, 'townHall');
  build(world, owner, 'townHall');
}

function maintainBuildOrder(world: World, owner: PlayerId): void {
  const player = world.player(owner);
  if (player.supplyCap - player.supplyUsed <= 2 || countBuilding(world, owner, 'farm') < 2) {
    ensureResources(world, owner, 'farm');
    build(world, owner, 'farm');
  }
  for (const kind of desiredBuildings) {
    if (!hasBuilding(world, owner, kind)) {
      ensureResources(world, owner, kind);
      build(world, owner, kind);
      return;
    }
  }
  if (player.supplyCap - player.supplyUsed <= 4) {
    ensureResources(world, owner, 'farm');
    build(world, owner, 'farm');
  }
}

function trainUnits(world: World, owner: PlayerId): void {
  const workers = unitsOf(world, owner, 'worker').length;
  for (const hall of buildingsOf(world, owner, 'townHall')) {
    if (workers < 8 && hall.queue.length === 0) {
      world.enqueueTraining(hall.id, 'worker');
    }
  }
  for (const barracks of buildingsOf(world, owner, 'barracks')) {
    if (barracks.queue.length > 1) {
      continue;
    }
    const choice = chooseMilitary(world, owner);
    if (!world.enqueueTraining(barracks.id, choice)) {
      world.enqueueTraining(barracks.id, 'melee');
    }
  }
}

function chooseMilitary(world: World, owner: PlayerId): UnitKind {
  if (world.hasRequirements(owner, ['barracks', 'lumberMill']) && world.player(owner).gold > 220 && world.player(owner).wood > 90) {
    return 'heavy';
  }
  if (world.hasRequirements(owner, ['barracks', 'lumberMill']) && world.tickCount % 2 === 0) {
    return 'ranged';
  }
  return 'melee';
}

function defendBase(world: World, owner: PlayerId): void {
  const threat = findThreat(world, owner);
  if (threat === undefined) {
    return;
  }
  for (const unit of military(world, owner)) {
    if (distance({ x: unit.x, y: unit.y }, threat.point) < 18) {
      world.issueAttack(unit.id, threat.id);
    }
  }
}

function launchWaves(world: World, owner: PlayerId): void {
  const player = world.player(owner);
  const firstWave = TICK_RATE * 60 * 3.5;
  const cadence = Math.max(TICK_RATE * 45, TICK_RATE * 95 - player.aiDifficulty * TICK_RATE * 10);
  if (world.tickCount < firstWave + player.wavesLaunched * cadence) {
    return;
  }
  const army = military(world, owner).filter(unit => unit.waveTag === undefined || player.wavesLaunched > unit.waveTag);
  const needed = 2 + player.aiDifficulty + player.wavesLaunched;
  if (army.length < needed) {
    return;
  }
  const target = enemyTarget(world, owner);
  if (target === undefined) {
    return;
  }
  const ids = army.slice(0, Math.min(army.length, needed + 2)).map(unit => unit.id);
  for (const unit of army) {
    unit.waveTag = player.wavesLaunched;
  }
  world.issueAttackMove(ids, target);
  player.wavesLaunched += 1;
}

function build(world: World, owner: PlayerId, kind: BuildingKind): EntityId | undefined {
  const worker = unitsOf(world, owner, 'worker').find(unit => unit.order.kind === 'idle') ?? unitsOf(world, owner, 'worker')[0];
  if (worker === undefined) {
    return undefined;
  }
  const site = findBuildSite(world, owner, kind);
  return site === undefined ? undefined : world.issueBuild(worker.id, kind, site);
}

function findBuildSite(world: World, owner: PlayerId, kind: BuildingKind): Point | undefined {
  const start = world.map.starts.find(candidate => candidate.player === owner);
  if (start === undefined) {
    throw new Error(`missing start for player ${owner}`);
  }
  for (const point of spiral({ x: start.x + (owner === 1 ? 4 : -6), y: start.y + 4 }, 16)) {
    const result = validatePlacement({ map: world.map, buildings: world.buildings.values(), units: world.units.values() }, kind, point);
    if (result.ok) {
      return point;
    }
  }
  return undefined;
}

function ensureResources(world: World, owner: PlayerId, kind: BuildingKind): void {
  const player = world.player(owner);
  const cost = buildingStats(kind).cost;
  if (player.gold < cost.gold) {
    player.gold = cost.gold;
  }
  if (player.wood < cost.wood) {
    player.wood = cost.wood;
  }
}

function unitsOf(world: World, owner: PlayerId, kind: UnitKind): ReturnType<typeof Array<UnitKind>> {
  return Array.from(world.units.values()).filter(unit => unit.owner === owner && unit.kind === kind);
}

function military(world: World, owner: PlayerId): ReturnType<typeof Array<UnitKind>> {
  return Array.from(world.units.values()).filter(unit => unit.owner === owner && unit.kind !== 'worker');
}

function buildingsOf(world: World, owner: PlayerId, kind: BuildingKind): ReturnType<typeof Array<BuildingKind>> {
  return Array.from(world.buildings.values()).filter(building => building.owner === owner && building.kind === kind && building.complete);
}

function hasBuilding(world: World, owner: PlayerId, kind: BuildingKind): boolean {
  return Array.from(world.buildings.values()).some(building => building.owner === owner && building.kind === kind);
}

function countBuilding(world: World, owner: PlayerId, kind: BuildingKind): number {
  return Array.from(world.buildings.values()).filter(building => building.owner === owner && building.kind === kind).length;
}

function enemyTarget(world: World, owner: PlayerId): Point | undefined {
  const enemy = world.enemyOf(owner);
  const building = Array.from(world.buildings.values()).find(candidate => candidate.owner === enemy);
  if (building === undefined) {
    return undefined;
  }
  return { x: Math.floor(building.x + building.w / 2), y: Math.floor(building.y + building.h / 2) };
}

function findThreat(world: World, owner: PlayerId): { id: EntityId; point: Point } | undefined {
  const ownBuildings = Array.from(world.buildings.values()).filter(building => building.owner === owner);
  for (const enemy of world.units.values()) {
    if (enemy.owner === owner) {
      continue;
    }
    if (ownBuildings.some(building => distance({ x: enemy.x, y: enemy.y }, { x: building.x + building.w / 2, y: building.y + building.h / 2 }) < 12)) {
      return { id: enemy.id, point: { x: enemy.x, y: enemy.y } };
    }
  }
  return undefined;
}

