import { TILE_SIZE } from '../sim/constants';
import { getTile } from '../sim/map/tiles';
import type { BuildingKind, EntityId, Point, Rect } from '../sim/types';
import { selectAt, selectBox, entityAtWorld } from '../sim/worldAccess';
import type { World } from '../sim/world';
import { computeHudLayout, hitTest, type HudElement } from './layout';

export interface CameraState {
  x: number;
  y: number;
  zoom: number;
}

export interface CanvasRectSource {
  getRect(): Rect;
}

export interface InputOptions {
  canvas: HTMLCanvasElement;
  world: World;
  camera: CameraState;
  rectSource?: CanvasRectSource;
  onPauseToggle?: () => void;
  onSpeedToggle?: () => void;
}

interface DragState {
  startScreen: Point;
  startWorld: Point;
  additive: boolean;
}

const dragThreshold = 5;

export class InputController {
  private readonly canvas: HTMLCanvasElement;
  private readonly world: World;
  private readonly camera: CameraState;
  private readonly rectSource: CanvasRectSource;
  private readonly onPauseToggle?: () => void;
  private readonly onSpeedToggle?: () => void;
  private drag?: DragState;
  private pendingBuild?: BuildingKind;

  public constructor(options: InputOptions) {
    this.canvas = options.canvas;
    this.world = options.world;
    this.camera = options.camera;
    this.rectSource = options.rectSource ?? { getRect: () => domRectToRect(this.canvas.getBoundingClientRect()) };
    this.onPauseToggle = options.onPauseToggle;
    this.onSpeedToggle = options.onSpeedToggle;
  }

  public bind(): void {
    this.canvas.addEventListener('mousedown', this.onMouseDown);
    this.canvas.addEventListener('mousemove', this.onMouseMove);
    this.canvas.addEventListener('mouseup', this.onMouseUp);
    this.canvas.addEventListener('contextmenu', this.onContextMenu);
    window.addEventListener('keydown', this.onKeyDown);
  }

  public unbind(): void {
    this.canvas.removeEventListener('mousedown', this.onMouseDown);
    this.canvas.removeEventListener('mousemove', this.onMouseMove);
    this.canvas.removeEventListener('mouseup', this.onMouseUp);
    this.canvas.removeEventListener('contextmenu', this.onContextMenu);
    window.removeEventListener('keydown', this.onKeyDown);
  }

  private readonly onMouseDown = (event: MouseEvent): void => {
    const screen = this.toCanvasPoint(event);
    const layout = computeHudLayout(this.canvasWidth(), this.canvasHeight());
    const hud = hitTest(layout, screen.x, screen.y);
    if (hud !== undefined) {
      this.handleHud(hud, screen);
      return;
    }
    if (event.button === 0) {
      this.drag = { startScreen: screen, startWorld: this.screenToWorld(screen), additive: event.shiftKey };
    } else if (event.button === 2) {
      this.issueContextOrder(this.screenToWorld(screen));
    }
  };

  private readonly onMouseMove = (event: MouseEvent): void => {
    const rect = this.rectSource.getRect();
    const margin = 18;
    if (event.clientX - rect.x < margin) {
      this.camera.x = Math.max(0, this.camera.x - 0.5);
    } else if (rect.x + rect.w - event.clientX < margin) {
      this.camera.x += 0.5;
    }
    if (event.clientY - rect.y < margin) {
      this.camera.y = Math.max(0, this.camera.y - 0.5);
    } else if (rect.y + rect.h - event.clientY < margin) {
      this.camera.y += 0.5;
    }
  };

  private readonly onMouseUp = (event: MouseEvent): void => {
    const drag = this.drag;
    this.drag = undefined;
    if (event.button !== 0 || drag === undefined) {
      return;
    }
    const screen = this.toCanvasPoint(event);
    const worldPoint = this.screenToWorld(screen);
    if (this.pendingBuild !== undefined) {
      this.confirmBuild(worldPoint);
      return;
    }
    if (Math.hypot(screen.x - drag.startScreen.x, screen.y - drag.startScreen.y) < dragThreshold) {
      selectAt(this.world, worldPoint, drag.additive);
      return;
    }
    selectBox(this.world, worldRect(drag.startWorld, worldPoint), drag.additive);
  };

  private readonly onContextMenu = (event: MouseEvent): void => {
    event.preventDefault();
    this.issueContextOrder(this.screenToWorld(this.toCanvasPoint(event)));
  };

  private readonly onKeyDown = (event: KeyboardEvent): void => {
    const digit = Number.parseInt(event.key, 10);
    if (event.key === ' ') {
      this.onPauseToggle?.();
      return;
    }
    if (event.key === 'ArrowLeft') {
      this.camera.x = Math.max(0, this.camera.x - 1);
    } else if (event.key === 'ArrowRight') {
      this.camera.x += 1;
    } else if (event.key === 'ArrowUp') {
      this.camera.y = Math.max(0, this.camera.y - 1);
    } else if (event.key === 'ArrowDown') {
      this.camera.y += 1;
    } else if (digit >= 1 && digit <= 9) {
      if (event.ctrlKey) {
        this.world.controlGroups.set(digit, Array.from(this.world.selectedIds));
      } else {
        this.world.selectedIds.clear();
        for (const id of this.world.controlGroups.get(digit) ?? []) {
          if (this.world.units.has(id) || this.world.buildings.has(id)) {
            this.world.selectedIds.add(id);
          }
        }
      }
    }
  };

  private handleHud(hud: HudElement, screen: Point): void {
    if (hud.kind === 'minimap') {
      this.camera.x = Math.max(0, ((screen.x - hud.rect.x) / hud.rect.w) * this.world.map.width - 10);
      this.camera.y = Math.max(0, ((screen.y - hud.rect.y) / hud.rect.h) * this.world.map.height - 8);
      return;
    }
    if (hud.action?.type === 'train') {
      for (const id of this.world.selectedIds) {
        this.world.enqueueTraining(id, hud.action.unit);
      }
    } else if (hud.action?.type === 'build') {
      this.pendingBuild = hud.action.building;
    } else if (hud.action?.type === 'pause') {
      this.onPauseToggle?.();
    } else if (hud.action?.type === 'speed') {
      this.onSpeedToggle?.();
    }
  }

  private issueContextOrder(worldPoint: Point): void {
    if (this.pendingBuild !== undefined) {
      this.confirmBuild(worldPoint);
      return;
    }
    const entity = entityAtWorld(this.world, worldPoint);
    const selectedUnits = Array.from(this.world.selectedIds).filter(id => this.world.units.has(id));
    if (entity !== undefined && entity.owner !== 1) {
      for (const id of selectedUnits) {
        this.world.issueAttack(id, entity.id);
      }
      return;
    }
    const tile = { x: Math.floor(worldPoint.x), y: Math.floor(worldPoint.y) };
    if (tile.x >= 0 && tile.y >= 0 && tile.x < this.world.map.width && tile.y < this.world.map.height) {
      const tileData = getTile(this.world.map, tile.x, tile.y);
      if (tileData.kind === 'goldMine' || tileData.kind === 'forest') {
        for (const id of selectedUnits) {
          this.world.issueHarvest(id, tile);
        }
        return;
      }
    }
    if (entity !== undefined && entity.owner === 1 && entity.type === 'building') {
      for (const id of selectedUnits) {
        this.world.issueRepair(id, entity.id);
      }
      return;
    }
    this.world.issueMove(selectedUnits, tile);
  }

  private confirmBuild(worldPoint: Point): void {
    const building = this.pendingBuild;
    this.pendingBuild = undefined;
    if (building === undefined) {
      return;
    }
    const worker = Array.from(this.world.selectedIds).find(id => this.world.units.get(id)?.kind === 'worker');
    if (worker !== undefined) {
      this.world.issueBuild(worker, building, { x: Math.floor(worldPoint.x), y: Math.floor(worldPoint.y) });
    }
  }

  private toCanvasPoint(event: MouseEvent): Point {
    const rect = this.rectSource.getRect();
    const width = this.canvasWidth();
    const height = this.canvasHeight();
    return { x: ((event.clientX - rect.x) / rect.w) * width, y: ((event.clientY - rect.y) / rect.h) * height };
  }

  private screenToWorld(point: Point): Point {
    return { x: this.camera.x + point.x / (TILE_SIZE * this.camera.zoom), y: this.camera.y + point.y / (TILE_SIZE * this.camera.zoom) };
  }

  private canvasWidth(): number {
    return this.canvas.width > 0 ? this.canvas.width : this.rectSource.getRect().w;
  }

  private canvasHeight(): number {
    return this.canvas.height > 0 ? this.canvas.height : this.rectSource.getRect().h;
  }
}

function worldRect(a: Point, b: Point): Rect {
  return { x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(a.x - b.x), h: Math.abs(a.y - b.y) };
}

function domRectToRect(rect: DOMRect): Rect {
  return { x: rect.left, y: rect.top, w: rect.width, h: rect.height };
}

import { TILE_SIZE } from '../sim/constants';
import { getTile } from '../sim/map/tiles';
import { FACTIONS, buildingStats, unitStats } from '../sim/stats';
import type { Building, Point, Rect, Unit } from '../sim/types';
import { mustGet } from '../sim/utils';
import type { World } from '../sim/world';
import { computeHudLayout, type HudLayout } from '../ui/layout';
import type { CameraState } from '../ui/input';

export interface RenderOptions {
  world: World;
  canvas: HTMLCanvasElement;
  camera: CameraState;
  paused: boolean;
  speed: 1 | 2;
}

export class Renderer {
  private readonly context: CanvasRenderingContext2D;

  public constructor(private readonly options: RenderOptions) {
    const context = options.canvas.getContext('2d');
    if (context === null) {
      throw new Error('Canvas 2D context unavailable');
    }
    this.context = context;
  }

  public render(): void {
    const canvas = this.options.canvas;
    const ctx = this.context;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    this.drawMap();
    this.drawEntities();
    this.drawFog();
    this.drawHud(computeHudLayout(canvas.width, canvas.height));
  }

  private drawMap(): void {
    const ctx = this.context;
    const world = this.options.world;
    const view = this.viewTileRect();
    for (let y = view.y; y < view.y + view.h; y += 1) {
      for (let x = view.x; x < view.x + view.w; x += 1) {
        if (x < 0 || y < 0 || x >= world.map.width || y >= world.map.height) {
          continue;
        }
        ctx.fillStyle = tileColor(getTile(world.map, x, y).kind);
        ctx.fillRect(...this.screenRect({ x, y, w: 1, h: 1 }));
      }
    }
  }

  private drawEntities(): void {
    for (const corpse of this.options.world.corpses) {
      this.context.globalAlpha = Math.max(0, corpse.remainingTicks / 80);
      this.context.fillStyle = '#34251d';
      this.fillCircle({ x: corpse.x, y: corpse.y }, 0.35);
      this.context.globalAlpha = 1;
    }
    for (const building of this.options.world.buildings.values()) {
      if (building.owner === 2 && !this.options.world.canSee(1, Math.floor(building.x), Math.floor(building.y))) {
        continue;
      }
      this.drawBuilding(building);
    }
    for (const unit of this.options.world.units.values()) {
      if (unit.owner === 2 && !this.options.world.canSee(1, unit.tile.x, unit.tile.y)) {
        continue;
      }
      this.drawUnit(unit);
    }
    for (const projectile of this.options.world.projectiles) {
      this.context.fillStyle = '#ffd76a';
      this.fillCircle({ x: projectile.x, y: projectile.y }, 0.12);
    }
  }

  private drawBuilding(building: Building): void {
    const theme = FACTIONS[building.faction];
    const ctx = this.context;
    ctx.fillStyle = building.complete ? theme.dark : '#777777';
    ctx.fillRect(...this.screenRect({ x: building.x, y: building.y, w: building.w, h: building.h }));
    ctx.strokeStyle = theme.secondary;
    ctx.lineWidth = 2;
    ctx.strokeRect(...this.screenRect({ x: building.x, y: building.y, w: building.w, h: building.h }));
    this.drawHpBar({ x: building.x, y: building.y - 0.15 }, building.hp / buildingStats(building.kind).hp, building.w);
  }

  private drawUnit(unit: Unit): void {
    const theme = FACTIONS[unit.faction];
    this.context.fillStyle = theme.primary;
    this.fillCircle({ x: unit.x, y: unit.y }, unit.kind === 'heavy' ? 0.38 : 0.3);
    this.context.fillStyle = theme.secondary;
    if (unit.kind === 'ranged') {
      this.fillCircle({ x: unit.x + 0.12, y: unit.y - 0.12 }, 0.09);
    }
    if (this.options.world.selectedIds.has(unit.id)) {
      this.context.strokeStyle = '#ffffff';
      this.strokeCircle({ x: unit.x, y: unit.y }, 0.45);
    }
    this.drawHpBar({ x: unit.x - 0.35, y: unit.y - 0.55 }, unit.hp / unitStats(unit.faction, unit.kind).hp, 0.7);
  }

  private drawFog(): void {
    const ctx = this.context;
    const fog = mustGet(this.options.world.fog, 1, 'fog');
    const view = this.viewTileRect();
    for (let y = view.y; y < view.y + view.h; y += 1) {
      for (let x = view.x; x < view.x + view.w; x += 1) {
        if (x < 0 || y < 0 || x >= this.options.world.map.width || y >= this.options.world.map.height) {
          continue;
        }
        const index = y * this.options.world.map.width + x;
        if (fog.visible[index] === 0) {
          ctx.fillStyle = fog.explored[index] === 1 ? 'rgba(0,0,0,0.45)' : '#000000';
          ctx.fillRect(...this.screenRect({ x, y, w: 1, h: 1 }));
        }
      }
    }
  }

  private drawHud(layout: HudLayout): void {
    this.drawPanel(layout.resourceBar.rect, '#111927');
    const player = this.options.world.player(1);
    this.context.fillStyle = '#ffffff';
    this.context.font = '16px sans-serif';
    this.context.fillText(`Gold ${Math.floor(player.gold)}   Wood ${Math.floor(player.wood)}   Supply ${player.supplyUsed}/${player.supplyCap}   Seed ${this.options.world.seed}`, 12, 23);
    this.context.fillText(`${this.options.paused ? 'Paused' : 'Running'} ${this.options.speed}x`, layout.resourceBar.rect.w - 220, 23);
    this.drawMinimap(layout.minimap.rect);
    this.drawPanel(layout.selectionPanel.rect, '#1c2635');
    for (const button of layout.buttons) {
      this.drawPanel(button.rect, '#2e4058');
      this.context.fillStyle = '#ffffff';
      this.context.font = '11px sans-serif';
      this.context.fillText(button.label, button.rect.x + 4, button.rect.y + 23);
    }
    if (this.options.world.outcome !== 'playing') {
      this.drawOutcome();
    }
  }

  private drawMinimap(rect: Rect): void {
    this.drawPanel(rect, '#0b0d13');
    const world = this.options.world;
    const fog = mustGet(world.fog, 1, 'fog');
    const sx = rect.w / world.map.width;
    const sy = rect.h / world.map.height;
    for (let y = 0; y < world.map.height; y += 1) {
      for (let x = 0; x < world.map.width; x += 1) {
        const index = y * world.map.width + x;
        this.context.fillStyle = fog.explored[index] === 0 ? '#000000' : tileColor(getTile(world.map, x, y).kind);
        if (fog.visible[index] === 0 && fog.explored[index] === 1) {
          this.context.globalAlpha = 0.45;
        }
        this.context.fillRect(rect.x + x * sx, rect.y + y * sy, Math.max(1, sx), Math.max(1, sy));
        this.context.globalAlpha = 1;
      }
    }
    const view = this.viewTileRect();
    this.context.strokeStyle = '#ffffff';
    this.context.strokeRect(rect.x + view.x * sx, rect.y + view.y * sy, view.w * sx, view.h * sy);
  }

  private drawOutcome(): void {
    const canvas = this.options.canvas;
    this.context.fillStyle = 'rgba(0,0,0,0.7)';
    this.context.fillRect(0, 0, canvas.width, canvas.height);
    this.context.fillStyle = '#ffffff';
    this.context.font = '48px sans-serif';
    this.context.fillText(this.options.world.outcome === 'victory' ? 'Victory' : 'Defeat', canvas.width / 2 - 90, canvas.height / 2);
  }

  private drawPanel(rect: Rect, color: string): void {
    this.context.fillStyle = color;
    this.context.fillRect(rect.x, rect.y, rect.w, rect.h);
    this.context.strokeStyle = '#8592a3';
    this.context.strokeRect(rect.x, rect.y, rect.w, rect.h);
  }

  private drawHpBar(point: Point, ratio: number, widthTiles: number): void {
    const [x, y, w] = this.screenRect({ x: point.x, y: point.y, w: widthTiles, h: 0.08 });
    this.context.fillStyle = '#440000';
    this.context.fillRect(x, y, w, 4);
    this.context.fillStyle = '#22cc44';
    this.context.fillRect(x, y, w * Math.max(0, Math.min(1, ratio)), 4);
  }

  private fillCircle(point: Point, radiusTiles: number): void {
    this.context.beginPath();
    this.context.arc((point.x - this.options.camera.x) * TILE_SIZE * this.options.camera.zoom, (point.y - this.options.camera.y) * TILE_SIZE * this.options.camera.zoom, radiusTiles * TILE_SIZE * this.options.camera.zoom, 0, Math.PI * 2);
    this.context.fill();
  }

  private strokeCircle(point: Point, radiusTiles: number): void {
    this.context.beginPath();
    this.context.arc((point.x - this.options.camera.x) * TILE_SIZE * this.options.camera.zoom, (point.y - this.options.camera.y) * TILE_SIZE * this.options.camera.zoom, radiusTiles * TILE_SIZE * this.options.camera.zoom, 0, Math.PI * 2);
    this.context.stroke();
  }

  private screenRect(rect: Rect): [number, number, number, number] {
    const scale = TILE_SIZE * this.options.camera.zoom;
    return [(rect.x - this.options.camera.x) * scale, (rect.y - this.options.camera.y) * scale, rect.w * scale, rect.h * scale];
  }

  private viewTileRect(): Rect {
    const scale = TILE_SIZE * this.options.camera.zoom;
    return { x: Math.floor(this.options.camera.x), y: Math.floor(this.options.camera.y), w: Math.ceil(this.options.canvas.width / scale) + 1, h: Math.ceil(this.options.canvas.height / scale) + 1 };
  }
}

function tileColor(kind: string): string {
  switch (kind) {
    case 'grass': return '#2d8a33';
    case 'dirt': return '#8a6a3a';
    case 'forest': return '#0d4f1b';
    case 'water': return '#1c5f9e';
    case 'rock': return '#686868';
    case 'goldMine': return '#d7ad35';
    case 'depletedMine': return '#76664e';
    default: return '#000000';
  }
}

import { SECONDS_PER_TICK, TICK_RATE } from './sim/constants';
import { seedFromUrl } from './sim/prng';
import type { Faction } from './sim/types';
import { World } from './sim/world';
import { Renderer } from './render/renderer';
import { InputController, type CameraState } from './ui/input';
import './style.css';

interface RunningGame {
  world: World;
  renderer: Renderer;
  input: InputController;
  camera: CameraState;
}

const canvas = document.querySelector<HTMLCanvasElement>('#game');
const menu = document.querySelector<HTMLDivElement>('#menu');
if (canvas === null || menu === null) {
  throw new Error('required DOM elements are missing');
}

const campaignSeed = seedFromUrl(window.location.search);
let selectedFaction: Faction = 'humans';
let selectedLevel = 1;
let unlocked = Number.parseInt(window.localStorage.getItem('warband-unlocked') ?? '1', 10);
let running: RunningGame | undefined;
let paused = false;
let speed: 1 | 2 = 1;
let accumulator = 0;
let previousTime = performance.now();

resizeCanvas();
window.addEventListener('resize', resizeCanvas);
showMenu();
requestAnimationFrame(frame);

function showMenu(): void {
  if (running !== undefined) {
    running.input.unbind();
    running = undefined;
  }
  menu.hidden = false;
  menu.innerHTML = '';
  const title = document.createElement('h1');
  title.textContent = 'Warband';
  const seed = document.createElement('p');
  seed.textContent = `Campaign seed: ${campaignSeed}`;
  const factionRow = document.createElement('div');
  factionRow.append(button('Humans', () => { selectedFaction = 'humans'; }));
  factionRow.append(button('Orcs', () => { selectedFaction = 'orcs'; }));
  const levelRow = document.createElement('div');
  for (let level = 1; level <= 5; level += 1) {
    const levelButton = button(level <= unlocked ? `Level ${level}` : `Locked ${level}`, () => { selectedLevel = level; startGame(); });
    levelButton.disabled = level > unlocked;
    levelRow.append(levelButton);
  }
  const start = button(`Start Level ${selectedLevel}`, startGame);
  menu.append(title, seed, factionRow, levelRow, start);
}

function startGame(): void {
  menu.hidden = true;
  paused = false;
  speed = 1;
  const world = World.create(campaignSeed, selectedLevel, { playerFaction: selectedFaction });
  const camera = { x: Math.max(0, world.map.starts[0].x - 10), y: Math.max(0, world.map.starts[0].y - 8), zoom: 1 };
  const renderer = new Renderer({ world, canvas, camera, paused, speed });
  const input = new InputController({ canvas, world, camera, onPauseToggle: () => { paused = !paused; }, onSpeedToggle: () => { speed = speed === 1 ? 2 : 1; } });
  input.bind();
  running = { world, renderer, input, camera };
}

function frame(time: number): void {
  const delta = Math.min(0.25, (time - previousTime) / 1000);
  previousTime = time;
  const game = running;
  if (game !== undefined) {
    if (!paused) {
      accumulator += delta * speed;
      while (accumulator >= SECONDS_PER_TICK) {
        game.world.step(1);
        accumulator -= SECONDS_PER_TICK;
      }
    }
    game.renderer.render();
    if (game.world.outcome === 'victory') {
      unlocked = Math.max(unlocked, Math.min(5, game.world.map.level + 1));
      window.localStorage.setItem('warband-unlocked', unlocked.toString());
    }
  }
  requestAnimationFrame(frame);
}

function resizeCanvas(): void {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}

function button(label: string, action: () => void): HTMLButtonElement {
  const item = document.createElement('button');
  item.textContent = label;
  item.addEventListener('click', action);
  return item;
}

export const fixedTickRate = TICK_RATE;

