html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05070a;
  color: #f4f4f4;
  font-family: system-ui, sans-serif;
}

#game {
  display: block;
  width: 100vw;
  height: 100vh;
}

#menu {
  position: fixed;
  inset: 8% auto auto 50%;
  transform: translateX(-50%);
  min-width: 420px;
  padding: 24px;
  background: rgba(12, 18, 28, 0.95);
  border: 1px solid #7d8da3;
  box-shadow: 0 16px 42px rgba(0, 0, 0, 0.45);
  text-align: center;
}

#menu button {
  margin: 6px;
  padding: 10px 14px;
  background: #2e4058;
  color: #fff;
  border: 1px solid #a9b6c8;
  cursor: pointer;
}

#menu button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
