import { BALANCE } from '../src/sim/stats';
import type { GameMap, Point, TileKind } from '../src/sim/types';
import { World } from '../src/sim/world';
import { createTile, getTile, setTileKind } from '../src/sim/map/tiles';

export function makeMap(width = 32, height = 32): GameMap {
  return {
    width,
    height,
    tiles: Array.from({ length: width * height }, () => createTile('grass')),
    starts: [
      { player: 1, x: 5, y: 5 },
      { player: 2, x: width - 6, y: height - 6 }
    ],
    level: 1,
    seed: 99,
    walkVersion: 0
  };
}

export function makeWorld(width = 32, height = 32): World {
  const world = new World(makeMap(width, height), 99, { aiEnabled: false, difficulty: 1 });
  world.units.clear();
  world.buildings.clear();
  world.projectiles.splice(0, world.projectiles.length);
  for (const player of world.players.values()) {
    player.supplyUsed = 0;
    player.supplyCap = 100;
    player.gold = 2000;
    player.wood = 2000;
  }
  return world;
}

export function setResource(map: GameMap, point: Point, kind: 'goldMine' | 'forest', amount?: number): void {
  setTileKind(map, point.x, point.y, kind);
  const tile = getTile(map, point.x, point.y);
  if (kind === 'goldMine') {
    tile.gold = amount ?? BALANCE.mineGold;
  } else {
    tile.wood = amount ?? BALANCE.forestWood;
  }
}

export function setBlock(map: GameMap, point: Point, kind: TileKind = 'rock'): void {
  setTileKind(map, point.x, point.y, kind);
}

export function stepUntil(world: World, predicate: () => boolean, maxTicks: number): boolean {
  for (let i = 0; i < maxTicks; i += 1) {
    if (predicate()) {
      return true;
    }
    world.step(1);
  }
  return predicate();
}

export function unitIds(world: World, owner = 1): number[] {
  return Array.from(world.units.values()).filter(unit => unit.owner === owner).map(unit => unit.id);
}

import { describe, expect, test } from 'vitest';
import { TICK_RATE } from '../src/sim/constants';
import { analyzePlayability, createCampaignMap, mapGrid } from '../src/sim/map/generator';
import { areAdjacentKindsAllowed } from '../src/sim/map/tiles';
import { findPath, pathDistance } from '../src/sim/pathfinding';
import { validateAdjacency } from '../src/sim/map/wfc';
import { World } from '../src/sim/world';
import { serializeWorld } from '../src/sim/worldAccess';
import { makeMap, setBlock } from './helpers';

describe('determinism and map generation', () => {
  test('same seed and order stream serializes identically after 1000 ticks', () => {
    const a = World.create(1234, 1, { aiEnabled: false });
    const b = World.create(1234, 1, { aiEnabled: false });
    const idsA = Array.from(a.units.values()).filter(unit => unit.owner === 1).map(unit => unit.id);
    const idsB = Array.from(b.units.values()).filter(unit => unit.owner === 1).map(unit => unit.id);
    a.issueMove(idsA, { x: 12, y: 12 });
    b.issueMove(idsB, { x: 12, y: 12 });
    a.step(1000);
    b.step(1000);
    expect(serializeWorld(a)).toEqual(serializeWorld(b));
  });

  test('different seeds produce different maps', () => {
    expect(serializeWorld(World.create(100, 2, { aiEnabled: false })).mapHash)
      .not.toEqual(serializeWorld(World.create(101, 2, { aiEnabled: false })).mapHash);
  });

  test('WFC output respects every cardinal adjacency rule', () => {
    const map = createCampaignMap(77, 3);
    expect(validateAdjacency(map)).toBe(true);
    for (let y = 0; y < map.height; y += 1) {
      for (let x = 0; x < map.width; x += 1) {
        const here = map.tiles[y * map.width + x].kind;
        if (x + 1 < map.width) {
          expect(areAdjacentKindsAllowed(here, map.tiles[y * map.width + x + 1].kind)).toBe(true);
        }
        if (y + 1 < map.height) {
          expect(areAdjacentKindsAllowed(here, map.tiles[(y + 1) * map.width + x].kind)).toBe(true);
        }
      }
    }
  });

  test('map generation is deterministic for a fixed seed and level', () => {
    const a = createCampaignMap(555, 4);
    const b = createCampaignMap(555, 4);
    expect(a.tiles.map(tile => tile.kind).join(',')).toEqual(b.tiles.map(tile => tile.kind).join(','));
  });

  test('playability pass succeeds across 20 seed-level combinations', () => {
    for (let seed = 1; seed <= 4; seed += 1) {
      for (let level = 1; level <= 5; level += 1) {
        const map = createCampaignMap(seed * 1000 + level, level);
        const report = analyzePlayability(map);
        expect(report.ok).toBe(true);
        expect(report.landDistance).toBeGreaterThanOrEqual(Math.max(map.width, map.height) * 0.6);
        expect(report.straightDistance).toBeGreaterThanOrEqual(Math.max(map.width, map.height) * 0.4);
        expect(report.resourcesNear).toBe(true);
      }
    }
  });
});

describe('A* pathfinding', () => {
  test('returns shortest 8-way path length on an open grid', () => {
    const grid = mapGrid(makeMap(8, 8));
    expect(pathDistance(grid, { x: 0, y: 0 }, { x: 3, y: 4 })).toBeCloseTo(3 * Math.SQRT2 + 1);
  });

  test('does not cut diagonally through blocked corners', () => {
    const map = makeMap(4, 4);
    setBlock(map, { x: 1, y: 0 });
    setBlock(map, { x: 0, y: 1 });
    const result = findPath(mapGrid(map), { x: 0, y: 0 }, { x: 2, y: 2 });
    expect(result.path[0]).not.toEqual({ x: 1, y: 1 });
  });

  test('reports unreachable targets instead of searching forever', () => {
    const map = makeMap(7, 7);
    for (let y = 1; y <= 3; y += 1) {
      for (let x = 1; x <= 3; x += 1) {
        if (x === 2 && y === 2) {
          continue;
        }
        setBlock(map, { x, y });
      }
    }
    const result = findPath(mapGrid(map), { x: 5, y: 5 }, { x: 2, y: 2 });
    expect(result.reachable).toBe(false);
    expect(result.visited).toBeLessThan(7 * 7);
  });

  test('boot smoke creates and steps all campaign levels', () => {
    for (let level = 1; level <= 5; level += 1) {
      const world = World.create(9000 + level, level, { aiEnabled: false });
      world.step(TICK_RATE * 30);
      expect(world.outcome).toBe('playing');
    }
  });
});

import { describe, expect, test } from 'vitest';
import { TICK_RATE } from '../src/sim/constants';
import { getTile } from '../src/sim/map/tiles';
import type { Building, Unit } from '../src/sim/types';
import { makeWorld, setResource, stepUntil } from './helpers';

function setupHarvestWorld(): { world: ReturnType<typeof makeWorld>; worker: Unit; hall: Building } {
  const world = makeWorld(24, 24);
  const hallId = world.spawnBuilding(1, 'townHall', { x: 3, y: 3 });
  const workerId = world.spawnUnit(1, 'worker', { x: 7, y: 5 });
  world.setStockpile(1, 0, 0);
  return { world, worker: world.units.get(workerId) ?? failUnit(), hall: world.requireBuilding(hallId) };
}

function failUnit(): Unit {
  throw new Error('missing worker');
}

describe('worker harvest loops', () => {
  test('worker gold loop completes three unattended round trips exactly', () => {
    const { world, worker } = setupHarvestWorld();
    setResource(world.map, { x: 10, y: 5 }, 'goldMine', 100);
    world.issueHarvest(worker.id, { x: 10, y: 5 });
    const delivered = stepUntil(world, () => world.player(1).gold === 30, TICK_RATE * 80);
    expect(delivered).toBe(true);
    expect(world.player(1).gold).toBe(30);
    expect(worker.order.kind).toBe('harvest');
  });

  test('wood depletion retargets the nearest reachable forest and keeps delivering', () => {
    const { world, worker } = setupHarvestWorld();
    setResource(world.map, { x: 10, y: 5 }, 'forest', 10);
    setResource(world.map, { x: 12, y: 5 }, 'forest', 40);
    world.issueHarvest(worker.id, { x: 10, y: 5 });
    const delivered = stepUntil(world, () => world.player(1).wood >= 20, TICK_RATE * 100);
    expect(delivered).toBe(true);
    expect(getTile(world.map, 10, 5).kind).toBe('grass');
    expect(worker.order.kind).toBe('harvest');
    expect(worker.order.kind === 'harvest' && worker.order.source).toEqual({ x: 12, y: 5 });
  });

  test('drop-off loss mid-carry reroutes to a surviving eligible drop-off', () => {
    const { world, worker, hall } = setupHarvestWorld();
    world.spawnBuilding(1, 'townHall', { x: 15, y: 3 });
    setResource(world.map, { x: 10, y: 5 }, 'goldMine', 100);
    world.issueHarvest(worker.id, { x: 10, y: 5 });
    expect(stepUntil(world, () => worker.cargo !== undefined, TICK_RATE * 20)).toBe(true);
    world.destroyEntity(hall.id);
    expect(stepUntil(world, () => world.player(1).gold === 10, TICK_RATE * 80)).toBe(true);
    expect(worker.cargo).toBeUndefined();
  });

  test('drop-off loss with no survivor leaves worker idle with cargo intact', () => {
    const { world, worker, hall } = setupHarvestWorld();
    setResource(world.map, { x: 10, y: 5 }, 'goldMine', 100);
    world.issueHarvest(worker.id, { x: 10, y: 5 });
    expect(stepUntil(world, () => worker.cargo !== undefined, TICK_RATE * 20)).toBe(true);
    world.destroyEntity(hall.id);
    expect(stepUntil(world, () => worker.order.kind === 'idle', TICK_RATE * 10)).toBe(true);
    expect(worker.cargo).toEqual({ kind: 'gold', amount: 10 });
  });

  test('mine exhaustion retargets another mine and never freezes mid-task', () => {
    const { world, worker } = setupHarvestWorld();
    setResource(world.map, { x: 10, y: 5 }, 'goldMine', 10);
    setResource(world.map, { x: 12, y: 5 }, 'goldMine', 40);
    world.issueHarvest(worker.id, { x: 10, y: 5 });
    const delivered = stepUntil(world, () => world.player(1).gold >= 20, TICK_RATE * 100);
    expect(delivered).toBe(true);
    expect(getTile(world.map, 10, 5).kind).toBe('depletedMine');
    expect(worker.order.kind).toBe('harvest');
  });

  test('exhausted mine with no replacement ends idle near drop-off', () => {
    const { world, worker } = setupHarvestWorld();
    setResource(world.map, { x: 10, y: 5 }, 'goldMine', 10);
    world.issueHarvest(worker.id, { x: 10, y: 5 });
    const idle = stepUntil(world, () => worker.order.kind === 'idle', TICK_RATE * 80);
    expect(idle).toBe(true);
    expect(worker.cargo).toBeUndefined();
    expect(world.player(1).gold).toBe(10);
  });
});

import { describe, expect, test } from 'vitest';
import { TICK_RATE } from '../src/sim/constants';
import type { Unit } from '../src/sim/types';
import { distance } from '../src/sim/utils';
import { makeWorld, setBlock } from './helpers';

function addChoke(world: ReturnType<typeof makeWorld>): void {
  for (let y = 0; y < world.map.height; y += 1) {
    if (y !== 10 && y !== 11) {
      setBlock(world.map, { x: 12, y });
    }
  }
}

function units(world: ReturnType<typeof makeWorld>): Unit[] {
  return Array.from(world.units.values());
}

describe('movement robustness', () => {
  test('12 units pass through a 2-tile chokepoint, arrive, and settle without stacking', () => {
    const world = makeWorld(28, 22);
    addChoke(world);
    const ids: number[] = [];
    for (let i = 0; i < 12; i += 1) {
      ids.push(world.spawnUnit(1, 'melee', { x: 3 + (i % 4), y: 7 + Math.floor(i / 4) }));
    }
    world.issueMove(ids, { x: 21, y: 10 });
    for (let tick = 0; tick < TICK_RATE * 60; tick += 1) {
      world.step(1);
      world.assertInvariants();
    }
    expect(units(world).every(unit => distance(unit.tile, { x: 21, y: 10 }) <= 5)).toBe(true);
    expect(units(world).every(unit => unit.order.kind === 'idle')).toBe(true);
    const before = units(world).map(unit => ({ id: unit.id, x: unit.x, y: unit.y }));
    world.step(TICK_RATE * 5);
    for (const snapshot of before) {
      const unit = world.units.get(snapshot.id);
      expect(unit?.x).toBe(snapshot.x);
      expect(unit?.y).toBe(snapshot.y);
    }
    assertNoStacks(world);
  });

  test('unreachable move order terminates at nearest reachable point', () => {
    const world = makeWorld(16, 16);
    for (let y = 4; y <= 6; y += 1) {
      for (let x = 4; x <= 6; x += 1) {
        if (x !== 5 || y !== 5) {
          setBlock(world.map, { x, y });
        }
      }
    }
    const id = world.spawnUnit(1, 'worker', { x: 10, y: 10 });
    const unit = world.units.get(id);
    if (unit === undefined) {
      throw new Error('missing unit');
    }
    world.issueMove([id], { x: 5, y: 5 });
    for (let tick = 0; tick < TICK_RATE * 25; tick += 1) {
      world.step(1);
      world.assertInvariants();
    }
    expect(unit.order.kind).toBe('idle');
    expect(distance(unit.tile, { x: 5, y: 5 })).toBeLessThan(5);
  });

  test('moving units do not pass through or shove idle units, including head-on corridor conflict', () => {
    const world = makeWorld(12, 11);
    for (let y = 0; y < 11; y += 1) {
      if (y !== 5) {
        for (let x = 0; x < 12; x += 1) {
          setBlock(world.map, { x, y });
        }
      }
    }
    const idleId = world.spawnUnit(1, 'worker', { x: 5, y: 5 });
    const moverId = world.spawnUnit(1, 'worker', { x: 2, y: 5 });
    const enemyMoverId = world.spawnUnit(1, 'worker', { x: 9, y: 5 });
    const idle = world.units.get(idleId);
    if (idle === undefined) {
      throw new Error('missing idle unit');
    }
    world.issueMove([moverId], { x: 8, y: 5 });
    world.issueMove([enemyMoverId], { x: 1, y: 5 });
    for (let tick = 0; tick < TICK_RATE * 25; tick += 1) {
      world.step(1);
      world.assertInvariants();
      expect(idle.x).toBe(5.5);
      expect(idle.y).toBe(5.5);
    }
    expect(Array.from(world.units.values()).every(unit => unit.order.kind === 'idle')).toBe(true);
  });
});

function assertNoStacks(world: ReturnType<typeof makeWorld>): void {
  const all = units(world);
  for (let i = 0; i < all.length; i += 1) {
    for (let j = i + 1; j < all.length; j += 1) {
      expect(distance({ x: all[i].x, y: all[i].y }, { x: all[j].x, y: all[j].y })).toBeGreaterThanOrEqual(0.5);
    }
  }
}

import { describe, expect, test } from 'vitest';
import { TICK_RATE } from '../src/sim/constants';
import { getTile } from '../src/sim/map/tiles';
import { validatePlacement } from '../src/sim/placement';
import { BUILDING_STATS, UNIT_STATS, buildingStats, costTotal, unitStats } from '../src/sim/stats';
import { computeDamage } from '../src/sim/systems/combat';
import type { Faction, UnitKind } from '../src/sim/types';
import { distance } from '../src/sim/utils';
import { makeWorld, setBlock, setResource, stepUntil } from './helpers';

const factions: Faction[] = ['humans', 'orcs'];

describe('stats sanity and combat', () => {
  test('unit and building stats satisfy genre sanity constraints for both factions', () => {
    for (const faction of factions) {
      const stats = UNIT_STATS[faction];
      expect(stats.heavy.hp).toBeGreaterThan(stats.melee.hp);
      expect(stats.melee.hp).toBeGreaterThan(stats.ranged.hp);
      expect(stats.ranged.hp).toBeGreaterThan(stats.worker.hp);
      expect(Math.min(...Object.values(BUILDING_STATS).map(item => item.hp))).toBeGreaterThan(Math.max(...Object.values(stats).map(item => item.hp)));
      expect(stats.heavy.damage).toBeGreaterThanOrEqual(stats.melee.damage);
      expect(stats.melee.damage).toBeGreaterThan(stats.worker.damage);
      expect(stats.worker.range).toBe(1);
      expect(stats.melee.range).toBe(1);
      expect(stats.heavy.range).toBe(1);
      expect(stats.ranged.range).toBeGreaterThanOrEqual(4);
      expect(BUILDING_STATS.guardTower.range).toBeGreaterThanOrEqual(stats.ranged.range);
      for (const unit of Object.values(stats)) {
        expect(unit.sight).toBeGreaterThanOrEqual(unit.range);
        const attacks = Math.ceil(unit.hp / Math.max(1, unit.damage - unit.armor));
        expect(attacks).toBeGreaterThanOrEqual(4);
        expect(attacks).toBeLessThanOrEqual(30);
      }
      const speeds = Object.values(stats).map(item => item.moveSpeed);
      expect(Math.max(...speeds)).toBeLessThanOrEqual(Math.min(...speeds) * 1.5);
      for (const speed of speeds) {
        expect(1 / speed).toBeGreaterThanOrEqual(0.3);
        expect(1 / speed).toBeLessThanOrEqual(1.2);
      }
      expect(costTotal(stats.heavy.cost)).toBeGreaterThan(Math.max(costTotal(stats.worker.cost), costTotal(stats.melee.cost), costTotal(stats.ranged.cost)));
      expect(stats.heavy.trainingTicks).toBeGreaterThan(Math.max(stats.worker.trainingTicks, stats.melee.trainingTicks, stats.ranged.trainingTicks));
    }
  });

  test('damage uses max(1, attack minus armor), death removes units and releases supply', () => {
    expect(computeDamage(3, 9)).toBe(1);
    expect(computeDamage(10, 3)).toBe(7);
    const world = makeWorld();
    const id = world.spawnUnit(1, 'worker', { x: 5, y: 5 });
    expect(world.player(1).supplyUsed).toBe(1);
    world.damageEntity(id, 1000);
    expect(world.units.has(id)).toBe(false);
    expect(world.player(1).supplyUsed).toBe(0);
  });

  test('ranged attacks create a projectile that applies damage on arrival', () => {
    const world = makeWorld();
    const archer = world.spawnUnit(1, 'ranged', { x: 5, y: 5 });
    const target = world.spawnUnit(2, 'worker', { x: 8, y: 5 });
    const hp = unitStats('orcs', 'worker').hp;
    world.issueAttack(archer, target);
    world.step(2);
    expect(world.projectiles.length).toBeGreaterThan(0);
    expect(stepUntil(world, () => world.projectiles.length === 0, TICK_RATE * 3)).toBe(true);
    expect(world.units.get(target)?.hp).toBeLessThan(hp);
  });
});

describe('production, repair, and placement', () => {
  test('supply cap blocks training, Farm completion unblocks it, and training completes', () => {
    const world = makeWorld(24, 24);
    const hall = world.spawnBuilding(1, 'townHall', { x: 3, y: 3 });
    const workers = Array.from({ length: 6 }, (_, index) => world.spawnUnit(1, 'worker', { x: 8 + index, y: 5 }));
    expect(world.enqueueTraining(hall, 'worker')).toBe(false);
    const farmId = world.issueBuild(workers[0], 'farm', { x: 8, y: 8 });
    expect(farmId).toBeDefined();
    expect(stepUntil(world, () => world.requireBuilding(farmId ?? 0).complete, buildingStats('farm').buildTicks + TICK_RATE * 10)).toBe(true);
    expect(world.player(1).supplyCap).toBe(10);
    expect(world.enqueueTraining(hall, 'worker')).toBe(true);
    const count = world.units.size;
    world.step(unitStats('humans', 'worker').trainingTicks + TICK_RATE);
    expect(world.units.size).toBe(count + 1);
  });

  test('surrounded production spawns at the nearest free walkable tile', () => {
    const world = makeWorld(24, 24);
    const barracks = world.spawnBuilding(1, 'barracks', { x: 8, y: 8 });
    for (let y = 7; y <= 11; y += 1) {
      for (let x = 7; x <= 11; x += 1) {
        const inside = x >= 8 && x <= 10 && y >= 8 && y <= 10;
        if (!inside) {
          world.spawnUnit(1, 'worker', { x, y });
        }
      }
    }
    const before = world.units.size;
    expect(world.enqueueTraining(barracks, 'melee')).toBe(true);
    world.step(unitStats('humans', 'melee').trainingTicks + TICK_RATE);
    expect(world.units.size).toBe(before + 1);
    const newest = Math.max(...Array.from(world.units.keys()));
    const spawned = world.units.get(newest);
    expect(spawned).toBeDefined();
    expect(spawned !== undefined && distance(spawned.tile, { x: 9, y: 9 })).toBeGreaterThan(2);
  });

  test('Worker repair restores a damaged building to full HP at a resource cost', () => {
    const world = makeWorld(24, 24);
    const hall = world.spawnBuilding(1, 'townHall', { x: 5, y: 5 });
    const worker = world.spawnUnit(1, 'worker', { x: 4, y: 5 });
    world.damageEntity(hall, 120);
    const beforeWood = world.player(1).wood;
    world.issueRepair(worker, hall);
    expect(stepUntil(world, () => world.requireBuilding(hall).hp === buildingStats('townHall').hp, TICK_RATE * 30)).toBe(true);
    expect(world.player(1).wood).toBeLessThan(beforeWood);
    expect(world.units.get(worker)?.order.kind).toBe('idle');
  });

  test('placement rejects terrain, resources, buildings, and units; accepted placement constructs', () => {
    const world = makeWorld(24, 24);
    const worker = world.spawnUnit(1, 'worker', { x: 4, y: 4 });
    setBlock(world.map, { x: 10, y: 10 });
    setResource(world.map, { x: 12, y: 10 }, 'goldMine');
    world.spawnBuilding(1, 'townHall', { x: 2, y: 2 });
    world.spawnUnit(1, 'worker', { x: 14, y: 10 });
    expect(validatePlacement({ map: world.map, buildings: world.buildings.values(), units: world.units.values() }, 'farm', { x: 10, y: 10 }).reason).toBe('terrain');
    expect(validatePlacement({ map: world.map, buildings: world.buildings.values(), units: world.units.values() }, 'farm', { x: 12, y: 10 }).reason).toBe('terrain');
    expect(getTile(world.map, 12, 10).kind).toBe('goldMine');
    expect(validatePlacement({ map: world.map, buildings: world.buildings.values(), units: world.units.values() }, 'farm', { x: 2, y: 2 }).reason).toBe('building');
    expect(validatePlacement({ map: world.map, buildings: world.buildings.values(), units: world.units.values() }, 'farm', { x: 14, y: 10 }).reason).toBe('unit');
    expect(validatePlacement({ map: world.map, buildings: world.buildings.values(), units: world.units.values() }, 'farm', { x: 16, y: 10 }).ok).toBe(true);
    const farm = world.issueBuild(worker, 'farm', { x: 16, y: 10 });
    expect(farm).toBeDefined();
  });

  test('unit stats table exposes all mirrored unit classes', () => {
    const kinds: UnitKind[] = ['worker', 'melee', 'ranged', 'heavy'];
    for (const faction of factions) {
      expect(kinds.map(kind => UNIT_STATS[faction][kind].label).every(Boolean)).toBe(true);
    }
  });
});

