import { describe, expect, test } from 'vitest';
import { TICK_RATE } from '../src/sim/constants';
import { World } from '../src/sim/world';
import { makeWorld } from './helpers';

describe('AI, outcomes, invariant fuzz, and performance', () => {
  test('difficulty 1 AI harvests, builds tech, trains army, launches a wave, and rebuilds a razed Barracks', () => {
    const world = World.create(4242, 1, { aiEnabled: true, difficulty: 1 });
    world.step(TICK_RATE * 60 * 5);
    const aiWorkers = Array.from(world.units.values()).filter(unit => unit.owner === 2 && unit.kind === 'worker');
    expect(aiWorkers.some(unit => unit.order.kind === 'harvest' && unit.order.resource === 'gold')).toBe(true);
    expect(aiWorkers.some(unit => unit.order.kind === 'harvest' && unit.order.resource === 'wood')).toBe(true);
    const barracks = Array.from(world.buildings.values()).find(building => building.owner === 2 && building.kind === 'barracks');
    expect(barracks).toBeDefined();
    expect(Array.from(world.units.values()).some(unit => unit.owner === 2 && unit.kind !== 'worker')).toBe(true);
    expect(world.player(2).wavesLaunched).toBeGreaterThan(0);
    if (barracks === undefined) {
      throw new Error('AI barracks missing');
    }
    world.destroyEntity(barracks.id);
    world.step(TICK_RATE * 80);
    expect(Array.from(world.buildings.values()).some(building => building.owner === 2 && building.kind === 'barracks')).toBe(true);
  });

  test('destroying all buildings triggers victory or defeat', () => {
    const world = World.create(33, 1, { aiEnabled: false });
    for (const building of Array.from(world.buildings.values()).filter(item => item.owner === 2)) {
      world.destroyEntity(building.id);
    }
    world.step(1);
    expect(world.outcome).toBe('victory');
    const loss = World.create(34, 1, { aiEnabled: false });
    for (const building of Array.from(loss.buildings.values()).filter(item => item.owner === 1)) {
      loss.destroyEntity(building.id);
    }
    loss.step(1);
    expect(loss.outcome).toBe('defeat');
  });

  test('invariant fuzz steps several seeded games for 2000 ticks', () => {
    for (const seed of [11, 22, 33]) {
      const world = World.create(seed, 2, { aiEnabled: true, difficulty: 2 });
      for (let tick = 0; tick < 2000; tick += 1) {
        world.step(1);
        world.assertInvariants();
      }
      expect(world.tickCount).toBe(2000);
    }
  });

  test('AI-vs-AI soak reaches an outcome within a 30-minute sim-time cap', { timeout: 60000 }, () => {
    const world = World.create(5151, 1, { aiEnabled: true, bothAi: true, difficulty: 1 });
    const target = world.map.starts[1];
    const ids: number[] = [];
    for (let i = 0; i < 14; i += 1) {
      ids.push(world.spawnUnit(1, 'heavy', { x: world.map.starts[0].x + (i % 4), y: world.map.starts[0].y + 5 + Math.floor(i / 4) }));
    }
    world.issueAttackMove(ids, { x: target.x, y: target.y });
    const cap = TICK_RATE * 60 * 30;
    for (let tick = 0; tick < cap && world.outcome === 'playing'; tick += 1) {
      world.step(1);
      if (tick % 10 === 0) {
        world.assertInvariants();
      }
    }
    expect(world.outcome).not.toBe('playing');
  });

  test('performance canary steps 100+ units for 1000 ticks under a generous bound', () => {
    const world = makeWorld(64, 64);
    const ids: number[] = [];
    for (let i = 0; i < 110; i += 1) {
      ids.push(world.spawnUnit(1, i % 4 === 0 ? 'ranged' : 'melee', { x: 5 + (i % 10), y: 5 + Math.floor(i / 10) }));
    }
    world.issueMove(ids, { x: 50, y: 50 });
    const started = performance.now();
    world.step(1000);
    const elapsed = performance.now() - started;
    expect(elapsed).toBeLessThan(10000);
    world.assertInvariants();
  });
});

// @vitest-environment jsdom
import { describe, expect, test } from 'vitest';
import { TILE_SIZE } from '../src/sim/constants';
import { setResource } from './helpers';
import { makeWorld } from './helpers';
import type { Point, Rect } from '../src/sim/types';
import { InputController, type CameraState } from '../src/ui/input';
import { computeHudLayout, hitTest, interactiveSiblingsDoNotOverlap } from '../src/ui/layout';

function setupInput(): { canvas: HTMLCanvasElement; world: ReturnType<typeof makeWorld>; camera: CameraState; input: InputController; rect: Rect } {
  const canvas = document.createElement('canvas');
  canvas.width = 640;
  canvas.height = 480;
  document.body.append(canvas);
  const world = makeWorld(40, 40);
  const camera = { x: 0, y: 0, zoom: 1 };
  const rect = { x: 20, y: 30, w: 1280, h: 960 };
  const input = new InputController({ canvas, world, camera, rectSource: { getRect: () => rect } });
  input.bind();
  return { canvas, world, camera, input, rect };
}

function client(rect: Rect, screen: Point, canvas: HTMLCanvasElement): Point {
  return { x: rect.x + (screen.x / canvas.width) * rect.w, y: rect.y + (screen.y / canvas.height) * rect.h };
}

function worldClient(rect: Rect, point: Point, canvas: HTMLCanvasElement): Point {
  return client(rect, { x: point.x * TILE_SIZE, y: point.y * TILE_SIZE }, canvas);
}

function mouse(canvas: HTMLCanvasElement, type: string, point: Point, button = 0, shiftKey = false): void {
  canvas.dispatchEvent(new MouseEvent(type, { clientX: point.x, clientY: point.y, button, buttons: button === 0 ? 1 : 2, shiftKey, bubbles: true }));
}

describe('input wiring through DOM events', () => {
  test('click selects a unit, shift-click adds, and drag box selects exactly enclosed units', () => {
    const { canvas, world, input, rect } = setupInput();
    const a = world.spawnUnit(1, 'worker', { x: 5, y: 5 });
    const b = world.spawnUnit(1, 'worker', { x: 7, y: 5 });
    const c = world.spawnUnit(1, 'worker', { x: 20, y: 20 });
    const aPoint = worldClient(rect, { x: 5.5, y: 5.5 }, canvas);
    mouse(canvas, 'mousedown', aPoint);
    mouse(canvas, 'mouseup', aPoint);
    expect(Array.from(world.selectedIds)).toEqual([a]);
    const bPoint = worldClient(rect, { x: 7.5, y: 5.5 }, canvas);
    mouse(canvas, 'mousedown', bPoint, 0, true);
    mouse(canvas, 'mouseup', bPoint, 0, true);
    expect(world.selectedIds.has(a)).toBe(true);
    expect(world.selectedIds.has(b)).toBe(true);
    const start = worldClient(rect, { x: 4, y: 4 }, canvas);
    const end = worldClient(rect, { x: 9, y: 7 }, canvas);
    mouse(canvas, 'mousedown', start);
    mouse(canvas, 'mouseup', end);
    expect(world.selectedIds.has(a)).toBe(true);
    expect(world.selectedIds.has(b)).toBe(true);
    expect(world.selectedIds.has(c)).toBe(false);
    input.unbind();
  });

  test('right-click dispatches move, attack, and harvest orders through the real control path', () => {
    const { canvas, world, input, rect } = setupInput();
    const worker = world.spawnUnit(1, 'worker', { x: 5, y: 5 });
    const enemy = world.spawnUnit(2, 'worker', { x: 12, y: 5 });
    world.selectedIds.add(worker);
    mouse(canvas, 'mousedown', worldClient(rect, { x: 10, y: 10 }, canvas), 2);
    expect(world.units.get(worker)?.order.kind).toBe('move');
    mouse(canvas, 'mousedown', worldClient(rect, { x: 12.5, y: 5.5 }, canvas), 2);
    expect(world.units.get(worker)?.order).toEqual({ kind: 'attack', targetId: enemy });
    setResource(world.map, { x: 15, y: 5 }, 'goldMine');
    mouse(canvas, 'mousedown', worldClient(rect, { x: 15.5, y: 5.5 }, canvas), 2);
    expect(world.units.get(worker)?.order.kind).toBe('harvest');
    input.unbind();
  });

  test('control groups and HUD train button enqueue through DOM events', () => {
    const { canvas, world, input, rect } = setupInput();
    const worker = world.spawnUnit(1, 'worker', { x: 5, y: 5 });
    const hall = world.spawnBuilding(1, 'townHall', { x: 10, y: 10 });
    world.selectedIds.add(worker);
    window.dispatchEvent(new KeyboardEvent('keydown', { key: '1', ctrlKey: true }));
    world.selectedIds.clear();
    window.dispatchEvent(new KeyboardEvent('keydown', { key: '1' }));
    expect(Array.from(world.selectedIds)).toEqual([worker]);
    world.selectedIds.clear();
    world.selectedIds.add(hall);
    const layout = computeHudLayout(canvas.width, canvas.height);
    const train = layout.buttons.find(button => button.id === 'train-worker');
    if (train === undefined) {
      throw new Error('train button missing');
    }
    const center = client(rect, { x: train.rect.x + train.rect.w / 2, y: train.rect.y + train.rect.h / 2 }, canvas);
    mouse(canvas, 'mousedown', center);
    expect(world.requireBuilding(hall).queue.length).toBe(1);
    input.unbind();
  });
});

describe('HUD layout', () => {
  test('interactive HUD rectangles fit and hit-test at centers for 1280x720', () => {
    assertLayout(1280, 720);
  });

  test('interactive HUD rectangles fit and hit-test at centers for 1920x1080', () => {
    assertLayout(1920, 1080);
  });
});

function assertLayout(width: number, height: number): void {
  const layout = computeHudLayout(width, height);
  expect(interactiveSiblingsDoNotOverlap(layout)).toBe(true);
  for (const element of layout.elements) {
    expect(element.rect.x).toBeGreaterThanOrEqual(0);
    expect(element.rect.y).toBeGreaterThanOrEqual(0);
    expect(element.rect.x + element.rect.w).toBeLessThanOrEqual(width);
    expect(element.rect.y + element.rect.h).toBeLessThanOrEqual(height);
    expect(hitTest(layout, element.rect.x + element.rect.w / 2, element.rect.y + element.rect.h / 2)?.id).toBe(element.id);
  }
  expect(layout.minimap.rect.y).toBeGreaterThanOrEqual(layout.resourceBar.rect.y + layout.resourceBar.rect.h);
  expect(layout.selectionPanel.rect.y).toBeGreaterThanOrEqual(layout.resourceBar.rect.y + layout.resourceBar.rect.h);
}

// @vitest-environment jsdom
import { describe, expect, test } from 'vitest';
import { TICK_RATE } from '../src/sim/constants';
import { Mulberry32, seedFromUrl } from '../src/sim/prng';
import { buildingStats, unitStats } from '../src/sim/stats';
import { World } from '../src/sim/world';
import { makeWorld, stepUntil } from './helpers';
import { InputController } from '../src/ui/input';
import { computeHudLayout } from '../src/ui/layout';

describe('additional core-system behavior', () => {
  test('seeded PRNG streams are reproducible and URL seed parsing is stable', () => {
    const a = new Mulberry32(123);
    const b = new Mulberry32(123);
    expect([a.next(), a.next(), a.int(10)]).toEqual([b.next(), b.next(), b.int(10)]);
    expect(seedFromUrl('?seed=987')).toBe(987);
  });

  test('fog marks friendly start visible and distant enemy unexplored after a tick', () => {
    const world = World.create(8080, 1, { aiEnabled: false });
    world.step(1);
    const own = world.map.starts[0];
    const enemy = world.map.starts[1];
    expect(world.canSee(1, own.x, own.y)).toBe(true);
    expect(world.canSee(1, enemy.x, enemy.y)).toBe(false);
  });

  test('supply-cap loss blocks new training while used exceeds cap', () => {
    const world = makeWorld(24, 24);
    const hall = world.spawnBuilding(1, 'townHall', { x: 2, y: 2 });
    const farm = world.spawnBuilding(1, 'farm', { x: 8, y: 2 });
    for (let i = 0; i < 8; i += 1) {
      world.spawnUnit(1, 'worker', { x: 4 + i, y: 8 });
    }
    expect(world.player(1).supplyCap).toBe(10);
    world.destroyEntity(farm);
    expect(world.player(1).supplyCap).toBe(6);
    expect(world.player(1).supplyUsed).toBe(8);
    expect(world.enqueueTraining(hall, 'worker')).toBe(false);
  });

  test('attack-move auto-acquires hostile targets entering sight', () => {
    const world = makeWorld();
    const archer = world.spawnUnit(1, 'ranged', { x: 5, y: 5 });
    world.spawnUnit(2, 'worker', { x: 8, y: 5 });
    world.issueAttackMove([archer], { x: 20, y: 5 });
    world.step(TICK_RATE);
    expect(world.projectiles.length).toBeGreaterThan(0);
  });

  test('Guard Tower static defense fires visible projectiles', () => {
    const world = makeWorld();
    world.spawnBuilding(1, 'guardTower', { x: 5, y: 5 });
    world.spawnUnit(2, 'melee', { x: 10, y: 6 });
    world.step(TICK_RATE);
    expect(world.projectiles.length).toBeGreaterThan(0);
  });

  test('queued training consumes exact stats-table duration before the unit appears', () => {
    const world = makeWorld();
    const hall = world.spawnBuilding(1, 'townHall', { x: 3, y: 3 });
    expect(world.enqueueTraining(hall, 'worker')).toBe(true);
    const count = world.units.size;
    world.step(unitStats('humans', 'worker').trainingTicks - 1);
    expect(world.units.size).toBe(count);
    world.step(1);
    expect(world.units.size).toBe(count + 1);
  });

  test('incomplete building HP reaches the stats-table maximum on construction completion', () => {
    const world = makeWorld(24, 24);
    const worker = world.spawnUnit(1, 'worker', { x: 4, y: 4 });
    const farm = world.issueBuild(worker, 'farm', { x: 7, y: 7 });
    if (farm === undefined) {
      throw new Error('farm placement failed');
    }
    expect(stepUntil(world, () => world.requireBuilding(farm).complete, buildingStats('farm').buildTicks + TICK_RATE * 10)).toBe(true);
    expect(world.requireBuilding(farm).hp).toBe(buildingStats('farm').hp);
  });
});

describe('minimap input', () => {
  test('clicking the minimap updates camera through injected client rectangle math', () => {
    const canvas = document.createElement('canvas');
    canvas.width = 800;
    canvas.height = 600;
    const world = makeWorld(64, 64);
    const camera = { x: 0, y: 0, zoom: 1 };
    const rect = { x: 100, y: 40, w: 1600, h: 1200 };
    const input = new InputController({ canvas, world, camera, rectSource: { getRect: () => rect } });
    input.bind();
    const minimap = computeHudLayout(canvas.width, canvas.height).minimap.rect;
    const screen = { x: minimap.x + minimap.w * 0.75, y: minimap.y + minimap.h * 0.75 };
    const client = { x: rect.x + (screen.x / canvas.width) * rect.w, y: rect.y + (screen.y / canvas.height) * rect.h };
    canvas.dispatchEvent(new MouseEvent('mousedown', { clientX: client.x, clientY: client.y, bubbles: true }));
    expect(camera.x).toBeGreaterThan(20);
    expect(camera.y).toBeGreaterThan(20);
    input.unbind();
  });
});

